@use '../../utils' as *;

/* ===========================================================
   Section 3 — Home 14 (Selected Series)
   =========================================================== */

.sec-3-home-14 {
    padding-top: 140px;
    padding-bottom: 140px;
    background-color: var(--at-neutral-0);

    @media #{$xxl},
    #{$xl} {
        padding-top: 100px;
        padding-bottom: 100px;
    }

    @media #{$lg},
    #{$md} {
        padding-top: 80px;
        padding-bottom: 80px;
    }

    @media #{$sm},
    #{$xs} {
        padding-top: 56px;
        padding-bottom: 56px;
    }

    &__inner {
        max-width: 1920px;
        margin: 0 auto;
        padding-left: 100px;
        padding-right: 100px;

        @media #{$x4l},
        #{$x3l},
        #{$xxl} {
            padding-left: 60px;
            padding-right: 60px;
        }

        @media #{$xl} {
            padding-left: 40px;
            padding-right: 40px;
        }

        @media #{$lg},
        #{$md} {
            padding-left: 30px;
            padding-right: 30px;
        }

        @media #{$sm},
        #{$xs} {
            padding-left: 16px;
            padding-right: 16px;
        }
    }

    /* Header row */
    &__head {
        display: flex;
        justify-content: space-between;
        align-items: flex-end;
        gap: 40px;
        margin-bottom: 64px;

        @media #{$lg},
        #{$md},
        #{$sm},
        #{$xs} {
            flex-direction: column;
            align-items: flex-start;
            gap: 28px;
        }
    }

    &__head-left {
        display: flex;
        flex-direction: column;
        gap: 24px;
        max-width: 1100px;
    }

    &__head-right {
        display: flex;
        flex-direction: column;
        align-items: flex-end;
        gap: 16px;
        max-width: 360px;

        @media #{$lg},
        #{$md},
        #{$sm},
        #{$xs} {
            align-items: flex-start;
            max-width: none;
        }
    }

    &__head-copy {
        font-family: var(--at-ff-body);
        font-size: 14px;
        line-height: 1.6;
        color: var(--at-neutral-500);
        text-align: right;

        @media #{$lg},
        #{$md},
        #{$sm},
        #{$xs} {
            text-align: left;

            br {
                display: none;
            }
        }
    }

    /* Eyebrow */
    &__eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 12px;
        font-family: var(--at-ff-body);
        font-size: 11px;
        line-height: 1;
        text-transform: uppercase;
    }

    &__eyebrow-dot {
        width: 8px;
        height: 8px;
        border-radius: 50%;
        background-color: var(--at-neutral-950);
    }

    &__eyebrow-key {
        font-weight: 600;
        color: var(--at-neutral-950);
        letter-spacing: 2px;
    }

    &__eyebrow-meta {
        font-weight: 400;
        color: var(--at-neutral-500);
        letter-spacing: 1.2px;
    }

    /* Title */
    &__title {
        font-family: var(--at-ff-heading);
        font-weight: 500;
        font-size: clamp(36px, 4.8vw, 80px);
        line-height: 1;
        letter-spacing: -0.025em;
        color: var(--at-neutral-950);

        @media #{$xs} {
            br {
                display: none;
            }
        }
    }

    /* Primary button */
    &__btn-primary {
        display: inline-flex;
        align-items: stretch;
        color: var(--at-neutral-0);
        text-decoration: none;
        transition: opacity 0.3s ease;

        .sec-3-home-14__btn-label {
            display: inline-flex;
            align-items: center;
            background: var(--at-neutral-900);
            color: var(--at-neutral-0);
            padding: 14px 27px;
            border-radius: 50px 0 0 50px;
            font-family: var(--at-ff-body);
            font-weight: 600;
            font-size: 16px;
            letter-spacing: -0.05em;
            line-height: 1;
            white-space: nowrap;
        }

        .sec-3-home-14__btn-icon {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            background: var(--at-neutral-900);
            color: var(--at-neutral-0);
            width: 50px;
            height: 50px;
            border-radius: 50%;
            margin-left: 2px;
        }

        &:hover {
            opacity: 0.85;
            color: var(--at-neutral-0);
        }
    }

    /* Grid */
    &__grid {
        display: grid;
        grid-template-columns: minmax(0, 960fr) minmax(0, 720fr);
        gap: 40px;
        align-items: start;

        @media #{$lg},
        #{$md},
        #{$sm},
        #{$xs} {
            grid-template-columns: 1fr;
            gap: 48px;
        }
    }

    /* Featured */
    &__featured {
        display: flex;
        flex-direction: column;
        gap: 24px;
    }

    &__featured-link {
        display: block;
        text-decoration: none;
        color: inherit;

        &:hover {
            .sec-3-home-14__featured-img {
                transform: scale(1.08) rotate(-1.2deg);
                filter: saturate(1.12) contrast(1.04);
            }

            .sec-3-home-14__featured-frame::after {
                opacity: 1;
            }

            .sec-3-home-14__featured-arrow {
                background: var(--at-neutral-950);
                color: var(--at-common-white);
                transform: rotate(-45deg);
            }

            .sec-3-home-14__featured-badge {
                background: var(--at-common-white);
                color: var(--at-neutral-950);
            }
        }
    }

    &__featured-frame {
        position: relative;
        aspect-ratio: 960 / 980;
        overflow: hidden;
        border-radius: 4px;
        background-color: var(--at-neutral-900);

        &::after {
            content: "";
            position: absolute;
            inset: 0;
            background: linear-gradient(180deg, rgba(0, 0, 0, 0) 35%, rgba(0, 0, 0, 0.45) 100%);
            opacity: 0;
            transition: opacity 0.6s ease;
            pointer-events: none;
            z-index: 1;
        }
    }

    &__featured-img {
        position: absolute;
        inset: 0;
        width: 100%;
        height: 100%;
        object-fit: cover;
        pointer-events: none;
        transform-origin: center;
        transition: transform 0.8s cubic-bezier(0.22, 1, 0.36, 1),
            filter 0.6s ease;
    }

    &__featured-overlay {
        position: absolute;
        inset: 0;
        padding: 28px;
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        color: var(--at-common-white);
        pointer-events: none;
        z-index: 2;

        @media #{$sm},
        #{$xs} {
            padding: 20px;
        }
    }

    &__featured-top {
        display: flex;
        justify-content: space-between;
        align-items: flex-start;
        gap: 16px;
    }

    &__featured-num {
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 11px;
        letter-spacing: 2px;
        color: var(--at-common-white);
    }

    &__featured-badge {
        display: inline-flex;
        align-items: center;
        border: 1px solid var(--at-common-white);
        color: var(--at-common-white);
        padding: 6px 12px;
        border-radius: 999px;
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: 10px;
        letter-spacing: 2px;
        line-height: 1;
        transition: background-color 0.4s ease, color 0.4s ease;
    }

    &__featured-bot {
        display: flex;
        justify-content: space-between;
        align-items: flex-end;
        gap: 24px;
    }

    &__featured-meta {
        display: flex;
        flex-direction: column;
        gap: 4px;
    }

    &__featured-title {
        font-family: var(--at-ff-heading);
        font-weight: 500;
        font-size: 48px;
        line-height: 1;
        letter-spacing: -1px;
        color: var(--at-common-white);

        @media #{$md},
        #{$sm},
        #{$xs} {
            font-size: 36px;
        }

        @media #{$xs} {
            font-size: 28px;
        }
    }

    &__featured-sub {
        font-family: var(--at-ff-body);
        font-weight: 400;
        font-size: 13px;
        letter-spacing: 0.4px;
        color: var(--at-common-white);
        opacity: 0.75;
    }

    &__featured-arrow {
        flex-shrink: 0;
        width: 50px;
        height: 50px;
        border-radius: 50%;
        background: var(--at-common-white);
        color: var(--at-neutral-950);
        display: inline-flex;
        align-items: center;
        justify-content: center;
        pointer-events: auto;
        transition: background-color 0.4s ease, color 0.4s ease,
            transform 0.5s cubic-bezier(0.22, 1, 0.36, 1);
    }

    &__featured-desc {
        font-family: var(--at-ff-body);
        font-weight: 400;
        font-size: 14px;
        line-height: 1.6;
        color: var(--at-neutral-500);
    }

    /* List */
    &__list {
        display: flex;
        flex-direction: column;
        gap: 0;
    }

    &__item {
        border-bottom: 1px solid var(--at-neutral-200);

        &:last-child {
            border-bottom: 0;
        }
    }

    &__item-link {
        display: grid;
        grid-template-columns: 220px 1fr;
        gap: 24px;
        align-items: center;
        padding: 24px 0;
        text-decoration: none;
        color: inherit;

        @media #{$xs} {
            grid-template-columns: 140px 1fr;
            gap: 16px;
        }

        &:hover {
            .sec-3-home-14__item-img img {
                transform: scale(1.08) rotate(-1.2deg);
                filter: saturate(1.12) contrast(1.04);
            }

            .sec-3-home-14__item-img::after {
                opacity: 1;
            }

            .sec-3-home-14__item-title {
                transform: translateX(6px);
            }

            .sec-3-home-14__item-view {
                transform: translateX(4px);
            }
        }
    }

    &__item-img {
        display: block;
        position: relative;
        aspect-ratio: 220 / 260;
        overflow: hidden;

        img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transform-origin: center;
            transition: transform 0.8s cubic-bezier(0.22, 1, 0.36, 1),
                filter 0.6s ease;
        }
    }

    &__item-meta {
        display: flex;
        flex-direction: column;
        gap: 12px;
        min-width: 0;
    }

    &__item-top {
        display: flex;
        justify-content: space-between;
        align-items: center;
        gap: 16px;
        font-family: var(--at-ff-body);
        font-size: 11px;
    }

    &__item-num {
        font-weight: 600;
        letter-spacing: 2px;
        color: var(--at-neutral-500);
    }

    &__item-view {
        font-weight: 500;
        letter-spacing: 0.4px;
        color: var(--at-neutral-950);
        transition: transform 0.4s ease;
    }

    &__item-title {
        font-family: var(--at-ff-heading);
        font-weight: 500;
        font-size: 42px;
        line-height: 1.05;
        letter-spacing: -0.8px;
        color: var(--at-neutral-950);
        transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1);

        @media #{$xl},
        #{$lg} {
            font-size: 36px;
        }

        @media #{$md},
        #{$sm} {
            font-size: 32px;
        }

        @media #{$xs} {
            font-size: 26px;
        }
    }

    &__item-sub {
        font-family: var(--at-ff-body);
        font-weight: 400;
        font-size: 13px;
        line-height: 1.5;
        letter-spacing: 0.2px;
        color: var(--at-neutral-500);
    }
}