@use '../../utils' as *;

/* Footer 12 (Home 12) — Always-dark CTA + main footer */
.footer-12 {
    background-color: #0f0f0f;
    color: #fefefe;
    position: relative;
}

/* ── CTA strip ──────────────────────────────────── */
.footer-12__cta {
    padding-top: 120px;
    padding-bottom: 120px;
    background-color: #0f0f0f;
}

.footer-12__cta-inner {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    row-gap: 32px;
}

.footer-12__cta-pill {
    display: inline-flex;
    align-items: center;
    column-gap: 8px;
    padding: 7px 14px;
    background-color: #212121;
    border: 1px solid #303030;
    border-radius: 999px;
}

.footer-12__cta-pill-dot {
    display: inline-block;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background-color: var(--at-theme-primary);
}

.footer-12__cta-pill-text {
    font-family: var(--at-ff-heading);
    font-weight: 500;
    font-size: 13px;
    line-height: 1;
    letter-spacing: -0.02em;
    color: #fefefe;
    white-space: nowrap;
}

.footer-12__cta-title {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: clamp(40px, 6.5vw, 84px);
    line-height: 1;
    letter-spacing: -0.05em;
    color: #fefefe;
    text-align: center;
}

.footer-12__cta-sub {
    font-family: var(--at-ff-heading);
    font-weight: 500;
    font-size: 18px;
    line-height: 1;
    letter-spacing: -0.02em;
    color: #b7b7b7;
}

.footer-12__cta-form {
    --footer12-cta-pad: 8px;          /* uniform inset between pill border and inner controls */
    --footer12-cta-control-h: 44px;   /* shared height of input + submit button */

    display: inline-flex;
    align-items: stretch;             /* so input matches button height; pad becomes visually equal on all sides */
    column-gap: var(--footer12-cta-pad);
    padding: var(--footer12-cta-pad);
    background-color: #212121;
    border: 1px solid #303030;
    border-radius: 999px;
    max-width: 100%;
}

/* `input.` selector matches the global theme rule `input[type="email"]` in
   specificity (1 element + 1 class) AND comes later in source order, so this
   reliably overrides the theme's height: 56px / line-height: 56px on this
   input only — without touching the global rule. */
input.footer-12__cta-input {
    flex: 1 1 auto;
    min-width: 0;
    height: var(--footer12-cta-control-h);
    padding: 0 16px;
    background: transparent;
    border: 0;
    color: #fefefe;
    font-family: var(--at-ff-heading);
    font-weight: 500;
    font-size: 15px;
    line-height: 1.4;
    letter-spacing: -0.02em;
    outline: none;

    &::placeholder {
        color: #585959;
    }
}

.footer-12__cta-submit {
    flex-shrink: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    height: var(--footer12-cta-control-h);
    padding: 0 22px;
    background-color: var(--at-theme-primary);
    color: #fefefe;
    border: 0;
    border-radius: 999px;
    font-family: var(--at-ff-heading);
    font-weight: 500;
    font-size: 14px;
    line-height: 1;
    letter-spacing: -0.02em;
    cursor: pointer;
    transition: background-color 0.3s ease, transform 0.3s ease;

    &:hover,
    &:focus-visible {
        background-color: #ff6128;
    }
}

/* ── Footer main ────────────────────────────────── */
.footer-12__main {
    padding-top: 72px;
    padding-bottom: 32px;
    background-color: #0f0f0f;
    display: flex;
    flex-direction: column;
}

.footer-12__divider {
    display: block;
    width: 100%;
    height: 1px;
    background-color: rgba(255, 255, 255, 0.1);
}

.footer-12__columns {
    display: grid;
    grid-template-columns: minmax(0, 1.6fr) repeat(3, minmax(0, 1fr)) minmax(0, 0.9fr);
    column-gap: 48px;
    row-gap: 48px;
    padding: 64px 0;
}

.footer-12__col {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    row-gap: 18px;
    min-width: 0;
}

.footer-12__col--brand {
    max-width: 420px;
    row-gap: 24px;
}

/* Brand */
.footer-12__brand {
    display: inline-flex;
    align-items: center;
    text-decoration: none;
    color: #fefefe;

    &:hover,
    &:focus-visible {
        color: #fefefe;
    }
}

.footer-12__brand-logo {
    display: block;
    height: 30px;
    width: auto;
}

.footer-12__brand-desc {
    margin: 0;
    font-family: var(--at-ff-heading);
    font-weight: 500;
    font-size: 15px;
    line-height: 1.6;
    letter-spacing: -0.02em;
    color: #b7b7b7;
}

/* Socials — uses .at-hero-social pill pattern (shared with footer-1).
   Compound selector (.at-hero-social.footer-12__socials) keeps specificity
   above the global .at-hero-social rule from _hero.scss, which is loaded
   later in the cascade and would otherwise win on equal specificity. */
.at-hero-social.footer-12__socials {
    justify-content: flex-start;
    gap: 8px;

    & a {
        color: var(--at-common-white);
        background: rgba(255, 255, 255, 0.06);
        border: 1px solid rgba(255, 255, 255, 0.32);

        &:hover,
        &:focus-visible {
            background: var(--at-theme-primary);
            border-color: var(--at-theme-primary);
            color: var(--at-common-white);
        }
    }
}

/* Column links */
.footer-12__col-title {
    margin: 0;
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 12px;
    line-height: 1;
    letter-spacing: 0.96px;
    color: #585959;
    text-transform: uppercase;
}

.footer-12__col-links {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    row-gap: 12px;

    a {
        font-family: var(--at-ff-heading);
        font-weight: 500;
        font-size: 15px;
        line-height: 1;
        letter-spacing: -0.02em;
        color: #fefefe;
        text-decoration: none;
        transition: color 0.3s ease;

        &:hover,
        &:focus-visible {
            color: var(--at-theme-primary);
        }
    }
}

/* Hours column */
.footer-12__col--hours {
    row-gap: 13px;
}

.footer-12__hours-value {
    font-family: var(--at-ff-heading);
    font-weight: 400;
    font-size: 20px;
    line-height: 1.25;
    letter-spacing: -0.05em;
    color: #fefefe;
}

/* ── Bottom bar ─────────────────────────────────── */
.footer-12__bottom {
    padding-top: 24px;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    column-gap: 24px;
    row-gap: 12px;
}

.footer-12__copy {
    font-family: var(--at-ff-heading);
    font-weight: 500;
    font-size: 13px;
    line-height: 1;
    letter-spacing: -0.02em;
    color: #585959;
}

.footer-12__legal {
    list-style: none;
    margin: 0;
    padding: 0;
    display: flex;
    flex-wrap: wrap;
    column-gap: 24px;
    row-gap: 8px;

    a {
        font-family: var(--at-ff-heading);
        font-weight: 500;
        font-size: 13px;
        line-height: 1;
        letter-spacing: -0.02em;
        color: #b7b7b7;
        text-decoration: none;
        transition: color 0.3s ease;

        &:hover,
        &:focus-visible {
            color: var(--at-theme-primary);
        }
    }
}

/* ── Responsive ─────────────────────────────────── */
@media #{$xxl} {
    .footer-12__cta {
        padding-top: 100px;
        padding-bottom: 100px;
    }
}

@media #{$xl} {
    .footer-12__cta {
        padding-top: 90px;
        padding-bottom: 90px;
    }
    .footer-12__columns {
        column-gap: 36px;
    }
}

@media #{$lg} {
    .footer-12__cta {
        padding-top: 80px;
        padding-bottom: 80px;
    }
    .footer-12__cta-inner {
        row-gap: 24px;
    }
    .footer-12__main {
        padding-top: 56px;
    }
    .footer-12__columns {
        grid-template-columns: minmax(0, 1.4fr) repeat(3, minmax(0, 1fr));
        padding: 48px 0;
        column-gap: 32px;
        row-gap: 32px;
    }
    .footer-12__col--hours {
        grid-column: 1 / -1;
        flex-direction: row;
        align-items: center;
        column-gap: 18px;
        row-gap: 0;
    }
}

@media #{$md} {
    .footer-12__cta {
        padding-top: 64px;
        padding-bottom: 64px;
    }
    .footer-12__cta-inner {
        row-gap: 20px;
    }
    .footer-12__main {
        padding-top: 48px;
    }
    .footer-12__columns {
        grid-template-columns: 1fr 1fr;
        column-gap: 32px;
        row-gap: 32px;
        padding: 40px 0;
    }
    .footer-12__col--brand {
        grid-column: 1 / -1;
        max-width: 100%;
    }
    .footer-12__col--hours {
        grid-column: 1 / -1;
        flex-direction: row;
        align-items: center;
        column-gap: 18px;
        row-gap: 0;
    }
}

@media #{$sm} {
    .footer-12__cta {
        padding-top: 56px;
        padding-bottom: 56px;
    }
    .footer-12__cta-inner {
        row-gap: 18px;
    }
    .footer-12__cta-form {
        width: 100%;
        max-width: 420px;
        --footer12-cta-control-h: 40px;
    }
    .footer-12__cta-submit {
        padding: 0 18px;
        font-size: 13px;
    }
    .footer-12__main {
        padding-top: 40px;
    }
    .footer-12__columns {
        grid-template-columns: 1fr 1fr;
        column-gap: 20px;
        row-gap: 28px;
        padding: 36px 0;
    }
    .footer-12__col--brand {
        grid-column: 1 / -1;
    }
    .footer-12__col--hours {
        grid-column: 1 / -1;
        flex-direction: row;
        align-items: center;
        column-gap: 14px;
        row-gap: 0;
    }
    .footer-12__bottom {
        column-gap: 18px;
    }
    .footer-12__legal {
        column-gap: 18px;
    }
}

@media #{$xs} {
    .footer-12__cta {
        padding-top: 48px;
        padding-bottom: 48px;
    }
    .footer-12__cta-inner {
        row-gap: 16px;
    }
    .footer-12__cta-pill-text {
        font-size: 12px;
    }
    .footer-12__cta-sub {
        font-size: 16px;
    }
    /* On mobile the pill wrapper looks cramped; lay out as two stacked
       full-width controls with their own rounded corners — no outer pill. */
    .footer-12__cta-form {
        width: 100%;
        flex-direction: column;
        column-gap: 0;
        row-gap: 10px;
        padding: 0;
        background-color: transparent;
        border: 0;
        border-radius: 0;
        --footer12-cta-control-h: 48px;
    }
    input.footer-12__cta-input {
        width: 100%;
        text-align: center;
        padding: 0 16px;
        background-color: #212121;
        border: 1px solid #303030;
        border-radius: 999px;
    }
    .footer-12__cta-submit {
        padding: 0 16px;
        width: 100%;
        font-size: 14px;
    }
    .footer-12__main {
        padding-top: 32px;
        padding-bottom: 24px;
    }
    .footer-12__columns {
        grid-template-columns: 1fr;
        column-gap: 0;
        row-gap: 24px;
        padding: 28px 0;
    }
    .footer-12__col {
        row-gap: 14px;
    }
    .footer-12__col--brand {
        row-gap: 18px;
    }
    .footer-12__col--hours {
        flex-direction: row;
        column-gap: 12px;
    }
    .footer-12__hours-value {
        font-size: 18px;
    }
    .footer-12__brand-logo {
        height: 26px;
    }
    .footer-12__brand-desc {
        font-size: 14px;
    }
    .footer-12__col-links a {
        font-size: 14px;
    }
    .footer-12__bottom {
        flex-direction: column;
        align-items: flex-start;
        row-gap: 10px;
    }
}
