@use '../../utils' as *;

/*----------------------------------------*/
/*  sec-7-home-15 (Home 15 — What we do)
/*----------------------------------------*/

.sec-7-home-15 {
    position: relative;
    background: var(--at-neutral-50, #f2f2f2);
    padding-top: 120px;
    padding-bottom: 140px;

    @media #{$xl} {
        padding-top: 100px;
        padding-bottom: 110px;
    }

    @media #{$lg}, #{$md} {
        padding-top: 80px;
        padding-bottom: 90px;
    }

    @media #{$sm}, #{$xs} {
        padding-top: 60px;
        padding-bottom: 60px;
    }

    /* ---- Header ---- */
    &__head {
        max-width: 1430px;
        margin-bottom: 60px;

        @media #{$lg}, #{$md} {
            margin-bottom: 48px;
        }

        @media #{$sm}, #{$xs} {
            margin-bottom: 36px;
        }
    }

    &__eyebrow {
        color: var(--at-neutral-900, #1d1d1d);
        margin-bottom: 16px;

        svg {
            flex-shrink: 0;
        }
    }

    &__eyebrow-text {
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 16px;
        line-height: 1.2;
        letter-spacing: -0.05em;
    }

    &__heading {
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: clamp(32px, 4.6vw, 64px);
        line-height: 1.125;
        letter-spacing: -0.05em;
        color: var(--at-neutral-900, #1d1d1d);
    }

    &__heading-muted {
        color: var(--at-neutral-300, #b7b7b7);
    }

    /* ---- Body ---- */
    &__body {
        align-items: flex-start;
    }

    /* ---- Left: image + caption ---- */
    &__media {
        margin-bottom: 28px;
    }

    &__media-frame {
        position: relative;
        border-radius: 16px;
        overflow: hidden;
        aspect-ratio: 551 / 345;
    }

    &__media-img {
        display: block;
        width: 100%;
        height: 100%;
        object-fit: cover;
        object-position: center;
    }

    &__caption {
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: clamp(18px, 1.4vw, 22px);
        line-height: 1.45;
        letter-spacing: -0.02em;
        color: var(--at-neutral-950, #0f0f0f);
        max-width: 551px;
    }

    /* ---- Right: services list ---- */
    &__services {
        border-top: 1px solid var(--at-neutral-200, #cdcccc);
        border-bottom: 1px solid var(--at-neutral-200, #cdcccc);
    }

    &__service {
        & + & {
            border-top: 1px solid var(--at-neutral-200, #cdcccc);
        }
    }

    &__service-link {
        display: flex;
        align-items: center;
        gap: 32px;
        padding: 28px 8px;
        color: inherit;
        text-decoration: none;
        transition: padding-left 0.35s ease;

        &:hover {
            padding-left: 16px;

            .sec-7-home-15__service-title {
                font-size: clamp(26px, 2.5vw, 36px);
            }

            .sec-7-home-15__service-fab {
                width: 56px;
                height: 56px;
                background: var(--at-theme-primary, #f0460e);
                border-color: var(--at-theme-primary, #f0460e);
                color: var(--at-neutral-0, #fefefe);

                svg {
                    width: 16px;
                    height: 15px;
                    stroke-width: 1.5;
                }
            }
        }

        @media #{$sm}, #{$xs} {
            gap: 16px;
            padding: 22px 4px;

            &:hover {
                padding-left: 8px;
            }
        }
    }

    &__service-index {
        flex-shrink: 0;
        width: 100px;
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: clamp(22px, 2.2vw, 32px);
        line-height: 1;
        letter-spacing: -0.03em;
        color: var(--at-neutral-950, #0f0f0f);

        @media #{$sm}, #{$xs} {
            width: 64px;
        }
    }

    &__service-title {
        flex: 1 1 auto;
        min-width: 0;
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: clamp(22px, 2vw, 28px);
        line-height: 1;
        letter-spacing: -0.03em;
        color: var(--at-neutral-950, #0f0f0f);
        transition: font-size 0.3s ease;
    }

    &__service-fab {
        flex-shrink: 0;
        width: 44px;
        height: 44px;
        border-radius: 50%;
        border: 1px solid var(--at-neutral-200, #cdcccc);
        background: transparent;
        color: var(--at-neutral-950, #0f0f0f);
        display: inline-flex;
        align-items: center;
        justify-content: center;
        transition: width 0.3s ease, height 0.3s ease, background 0.3s ease, color 0.3s ease, border-color 0.3s ease;

        svg {
            transition: width 0.3s ease, height 0.3s ease, stroke-width 0.3s ease;
        }
    }

    /* ---- CTA block ---- */
    &__cta-block {
        max-width: 590px;
        margin-top: 64px;

        @media #{$lg}, #{$md} {
            margin-top: 48px;
        }

        @media #{$sm}, #{$xs} {
            margin-top: 36px;
        }
    }

    &__cta-mark {
        display: inline-flex;
        width: 40px;
        height: 40px;
        margin-bottom: 24px;
    }

    &__cta-copy {
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: clamp(16px, 1.3vw, 20px);
        line-height: 1.5;
        letter-spacing: -0.02em;
        color: var(--at-neutral-900, #1d1d1d);
        margin-bottom: 28px;
    }

    &__cta-actions {
        gap: 0;
    }
}
