@use '../../utils' as *;

/* ===========================================================
   Section 3 — Home 15 (Brand strip with auto-marquee)
   =========================================================== */

.sec-3-home-15 {
    overflow-x: hidden;
    background-color: var(--at-neutral-0);
    padding-top: 24px;
    padding-bottom: 24px;

    @media #{$sm}, #{$xs} {
        padding-top: 16px;
        padding-bottom: 16px;
    }

    /* carouselTicker plugin handles infinite horizontal scroll on the ul. */
    &__strip {
        width: 100%;
    }

    /* Match Figma fill + responsive card sizes. */
    .at-brand-item {
        background-color: var(--at-neutral-50);

        @media #{$xl}, #{$lg} {
            width: 170px;
            height: 170px;
        }

        @media #{$sm} {
            width: 150px;
            height: 150px;
        }

        @media #{$xs} {
            width: 140px;
            height: 140px;
        }
    }
}
