@use '../../utils' as *;

/*------------------------------------------------------------------
  Home 8 — Section 7 (Image rails with scroll-move-right/left)
------------------------------------------------------------------*/

.sec-7-home-8 {
    background-color: var(--at-neutral-0);
    padding-top: clamp(70px, 6vw, 130px);
    padding-bottom: clamp(70px, 6vw, 130px);

    &__container {
        padding-left: clamp(20px, 5.2vw, 100px);
        padding-right: clamp(20px, 5.2vw, 100px);
    }

    &__title {
        font-size: clamp(36px, 3.75vw, 72px);
        font-weight: 600;
        line-height: 1.05;
        letter-spacing: -0.05em;
        color: var(--at-neutral-900);
        max-width: 920px;
    }

    &__cta {
        background: var(--at-neutral-900);
    }

    &__rails {
        margin-top: clamp(28px, 3.2vw, 55px);
        overflow: hidden;
    }

    &__rail {
        padding: 0;

        // Ensure the swiper fills width and looks like a rail
        .swiper {
            width: 100%;
        }

        .swiper-slide {
            width: auto;
        }

        .about-me-slider-thumb {
            overflow: hidden;
            border-radius: 16px;
            background: var(--at-neutral-300);

            img {
                width: 100%;
                height: 100%;
                object-fit: cover;
                display: block;
            }
        }
    }

    // Row 2: taller cards (780px)
    &__rail--reverse {
        margin-top: 30px;

        // Visual reverse direction without affecting image orientation
        transform: scaleX(-1);

        .swiper,
        .swiper-slide,
        .about-me-slider-thumb,
        img {
            transform: scaleX(-1);
        }
    }

    &__about {
        margin-top: clamp(34px, 3.8vw, 72px);
        justify-content: flex-end;
        max-width: 820px;
        margin-left: auto;
    }

    &__mark {
        flex: 0 0 83px;
        width: 83px;
        height: 83px;
        color: var(--at-neutral-900);
    }

    &__desc {
        font-size: 36px;
        font-weight: 600;
        letter-spacing: -0.05em;
        line-height: 1.35;
        color: var(--at-neutral-900);
        max-width: 700px;
    }

    &__desc-muted {
        color: var(--at-neutral-300);
        font-weight: 600;
    }

    @media (max-width: 1399px) {
        &__rail .about-me-slider-thumb {
            height: 420px;
        }

        &__rail--reverse .about-me-slider-thumb {
            height: 520px;
        }

        &__desc {
            font-size: 24px;
        }
    }

    @media (max-width: 767px) {
        &__rail .about-me-slider-thumb {
            height: 300px;
        }

        &__rail--reverse .about-me-slider-thumb {
            height: 360px;
        }

        &__mark {
            width: 58px;
            height: 58px;
            flex-basis: 58px;
        }
    }
}