@use '../../utils' as *;

/*------------------------------------------------------------------
  Home 8 — Section 9 (CTA)
------------------------------------------------------------------*/

.sec-9-home-8 {
    position: relative;
    background: var(--at-neutral-900);
    overflow: hidden;
    padding-top: clamp(80px, 7vw, 140px);
    padding-bottom: clamp(80px, 7vw, 140px);

    &__bg {
        position: absolute;
        inset: 0;
        z-index: 0;
        pointer-events: none;

        img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            display: block;
            filter: blur(69px);
            transform: scale(1.08);
            opacity: 0.65;
        }
    }

    &__container {
        position: relative;
        z-index: 1;
        padding-left: clamp(20px, 5.2vw, 100px);
        padding-right: clamp(20px, 5.2vw, 100px);
    }

    &__title {
        font-size: clamp(36px, 3.75vw, 72px);
        font-weight: 600;
        line-height: 1.05;
        letter-spacing: -0.05em;
        color: var(--at-neutral-0);
        max-width: 660px;
        margin-bottom: 18px;
    }

    &__lead {
        font-size: clamp(16px, 1.15vw, 22px);
        font-weight: 500;
        letter-spacing: -0.05em;
        color: rgba(var(--at-neutral-0-rgb), 0.92);
        max-width: 430px;
        margin-bottom: 38px;
    }

    &__cta {
        display: inline-flex;
        align-items: center;
    }

    &__cta-btn {
        height: 50px;
        display: inline-flex;
        align-items: center;
        padding: 0 27px;
        border-radius: 50px;
        background: var(--at-neutral-0);
        color: var(--at-neutral-900);
        font-size: 16px;
        font-weight: 600;
        letter-spacing: -0.05em;
        text-decoration: none;
        transition: transform 0.25s ease, background 0.25s ease;

        &:hover {
            transform: translateY(-2px);
        }
    }

    &__cta-icon {
        width: 50px;
        height: 50px;
        border-radius: 100px;
        background: var(--at-neutral-0);
        display: inline-flex;
        align-items: center;
        justify-content: center;
        margin-left: 0;
        text-decoration: none;
        transition: transform 0.25s ease;

        &:hover {
            transform: translateY(-2px);
        }

        img {
            width: 24px;
            height: 24px;
            display: block;
        }
    }

    &__card {
        display: block;
        border-radius: 16px;
        overflow: hidden;
        background: var(--at-neutral-100);
        position: relative;
        height: 457px;
        text-decoration: none;
    }

    &__card-media {
        position: absolute;
        inset: 0;
    }

    &__card-figure {
        position: absolute;
        left: 50%;
        top: 0;
        transform: translateX(-50%);
        width: 610px;
        height: 457px;
        object-fit: cover;
        display: block;
        pointer-events: none;
    }

    &__card-visors {
        position: absolute;
        left: 50%;
        bottom: 0;
        transform: translateX(-50%);
        width: 100%;
        height: auto;
        -o-object-fit: cover;
        object-fit: cover;
        display: block;
        pointer-events: none;
        mix-blend-mode: multiply;
        opacity: 1;
    }

    &__card-overlay {
        position: absolute;
        left: 43px;
        right: 43px;
        bottom: 38px;
        z-index: 2;
        color: #fff;
    }

    &__card-kicker {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        font-size: 16px;
        font-weight: 600;
        letter-spacing: -0.05em;
        text-transform: uppercase;
        margin-bottom: 12px;

        img {
            width: 14px;
            height: 13px;
            display: block;
        }
    }

    &__card-text {
        font-size: 24px;
        font-weight: 600;
        letter-spacing: -0.05em;
        max-width: 360px;
        line-height: 1.25;
        color: #fff;
    }

    @media (max-width: 1199px) {
        &__card {
            height: auto;
            min-height: 380px;
        }
    }
}