@use '../../utils' as *;

/*----------------------------------------*/
/*  sec-5-home-9 (Home 9 — Marquee / contact)
/*----------------------------------------*/

.sec-5-home-9 {
    --sec5-text: var(--at-neutral-0, #fefefe);

    position: relative;
    min-height: clamp(520px, 78vh, 920px);
    padding-top: clamp(72px, 8.2vw, 158px);
    padding-bottom: clamp(56px, 6vw, 120px);
    background: var(--at-neutral-200, #cdcccc);

    [data-bs-theme='dark'] & {
        --sec5-text: var(--at-neutral-950, #f4f4f4);
    }

    &__bg {
        position: absolute;
        inset: 0;
        overflow: hidden;
        pointer-events: none;
        z-index: 0;
    }

    &__bg-img {
        position: absolute;
        inset: 0;
        width: 100%;
        height: 100%;
        object-fit: cover;
        object-position: center center;
 /* Source asset is 1024×512; avoid extra CSS scale — export @2x for retina. */
    }

    &__container {
        position: relative;
        z-index: 1;
        max-width: 2200px;
        margin: 0 auto;
        padding-left: clamp(20px, 5.2vw, 100px);
        padding-right: clamp(20px, 5.2vw, 100px);
        mix-blend-mode: difference
    }

    &__meta {
        margin-bottom: clamp(32px, 4vw, 72px);
    }

    &__block {
        display: flex;
        flex-direction: column;
        gap: clamp(16px, 1.25vw, 24px);
    }

    &__label {
        margin: 0;
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: 12px;
        line-height: 1;
        letter-spacing: -0.02em;
        text-transform: uppercase;
        color: var(--sec5-text);
        opacity: 0.5;
    }

    &__value {
        margin: 0;
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: clamp(18px, 1.25vw, 24px);
        line-height: 1.35;
        letter-spacing: -0.05em;
        color: var(--sec5-text);

        /* Global `p {}` uses --at-neutral-500; override for stacked contact lines */
        p {
            margin-bottom: 0;
            color: inherit;
        }

        &--stack {
            display: flex;
            flex-direction: column;
            gap: 7px;
        }
    }

    &__mailto {
        color: inherit;
        text-decoration: none;
        transition: opacity 0.25s ease;

        &:hover {
            opacity: 0.85;
        }
    }

    &__marquee-shell {
        overflow-x: hidden;
        overflow-y: visible;
        width: 100%;
        margin-bottom: clamp(28px, 3vw, 48px);
        position: relative;
        z-index: 2;
        min-height: clamp(4.5rem, 15vw, 14rem);
        padding-block: clamp(0.25rem, 0.6vw, 0.75rem);
    }

    /* Blend on wrapper only — children must not create separate blend layers with GSAP/CSS transform conflicts */
    &__marquee {
        mix-blend-mode: difference;
        color: var(--at-neutral-0, #fefefe);

        .at-marquee__track {
            display: flex;
            width: max-content;
            will-change: transform;
            animation: sec5-home-9-marquee 55s linear infinite;
        }

        .at-marquee__group {
            display: inline-flex;
            align-items: center;
            flex-shrink: 0;
            white-space: nowrap;
        }
    }

    &__marquee-text {
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: clamp(42px, 10.3vw, 198px);
        line-height: 1.05;
        letter-spacing: -0.05em;
        color: inherit;
        -webkit-font-smoothing: antialiased;
    }

    &__marquee-sep {
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: clamp(42px, 10.3vw, 198px);
        line-height: 1.05;
        letter-spacing: -0.05em;
        opacity: 0.85;
        color: inherit;
        -webkit-font-smoothing: antialiased;
    }

    &__cta-wrap {
        display: flex;
        justify-content: center;
    }

    &__cta {
        display: inline-flex;
        align-items: center;
        height: 50px;
        padding: 0 5px 0 27px;
        border-radius: 50px;
        background: var(--at-theme-primary);
        text-decoration: none;
        color: var(--at-neutral-0, #fefefe) !important;
        gap: 10px;
        transition: filter 0.25s ease;

        &:hover {
            filter: brightness(1.05);
            color: var(--at-neutral-0, #fefefe) !important;
        }
    }

    &__cta-label {
        display: inline-flex;
        align-items: center;
        padding: 0;
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 16px;
        line-height: 1;
        letter-spacing: -0.05em;
    }

    &__cta-icon {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        flex-shrink: 0;
        width: 40px;
        height: 40px;
        border-radius: 50%;

        img {
            display: block;
            width: 24px;
            height: 24px;
        }
    }
}

@keyframes sec5-home-9-marquee {
    from {
        transform: translate3d(0, 0, 0);
    }

    to {
        transform: translate3d(-50%, 0, 0);
    }
}

@media (prefers-reduced-motion: reduce) {
    .sec-5-home-9__marquee .sec-5-home-9__marquee-track {
        animation: none;
        transform: none;
    }
}