@use '../../utils' as *;

/*----------------------------------------*/
/*  sec-3-home-10 (Home 10 — Selected projects / masonry)
/*----------------------------------------*/

.sec-3-home-10 {
    position: relative;
    padding-top: clamp(56px, 7vw, 120px);
    padding-bottom: clamp(64px, 9vw, 140px);
    background: var(--at-neutral-0);

    &__container {
        max-width: 2200px;
        margin: 0 auto;
        padding-left: clamp(20px, 5.2vw, 100px);
        padding-right: clamp(20px, 5.2vw, 100px);
    }

    &__header {
        margin-bottom: clamp(40px, 6vw, 80px) !important;
    }

    &__eyebrow-text {
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 16px;
        line-height: 1.2;
        letter-spacing: -0.05em;
        color: var(--at-neutral-900);
    }

    &__title {
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: clamp(36px, 5.5vw, 72px);
        line-height: 1.05;
        letter-spacing: -0.05em;
        text-transform: uppercase;
        color: var(--at-neutral-950);
        text-wrap: balance;
    }

    &__intro {
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: clamp(18px, 1.5vw, 22px);
        line-height: 1.45;
        letter-spacing: -0.05em;
        color: var(--at-neutral-900);

        strong {
            font-weight: 700;
            color: var(--at-neutral-950);
        }
    }

    &__grid {
        display: grid;
        gap: clamp(28px, 4vw, 40px);

        @media (min-width: 992px) {
            grid-template-columns: minmax(0, 0.372fr) minmax(0, 0.628fr);
            align-items: start;
        }
    }

    &__card {
        display: flex;
        flex-direction: column;
        gap: clamp(20px, 2.2vw, 28px);

        @media (min-width: 992px) {
            &--pos1 {
                grid-column: 1;
                grid-row: 1;
            }

            &--pos2 {
                grid-column: 2;
                grid-row: 1;
            }

            &--pos3 {
                grid-column: 1;
                grid-row: 2;
            }

            &--pos4 {
                grid-column: 2;
                grid-row: 2;
            }

            &--pos5 {
                grid-column: 2;
                grid-row: 3;
            }
        }
    }

    &__media {
        display: block;
        position: relative;
        width: 100%;
        overflow: hidden;
        background: transparent;
        text-decoration: none;
        transition: opacity 0.3s ease;

        &:hover {
            opacity: 0.92;
        }

        img {
            display: block;
            width: 100%;
            height: 100%;
            object-fit: cover;
        }
    }

    &__body {
        display: flex;
        flex-direction: column;
        gap: 16px;
        max-width: 380px;
    }

    &__name {
        margin: 0;
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: clamp(20px, 1.8vw, 24px);
        line-height: 1.2;
        letter-spacing: -0.05em;
        text-transform: uppercase;

        a {
            color: var(--at-neutral-900);
            text-decoration: none;
            transition: color 0.25s ease;

            &:hover {
                color: var(--at-theme-primary);
            }
        }
    }

    &__tag {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        padding: 10px 19px;
        border-radius: 32px;
        border: 1px solid var(--at-neutral-100);
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 12px;
        line-height: 1;
        letter-spacing: -0.02em;
        color: var(--at-neutral-900);
    }
}