@use '../../utils' as *;

/* Home 13 / Section 5 — Our Expertise */
.sec-5-home-13 {
    background-color: var(--at-neutral-50);
    padding: 120px 96px;
}

.sec-5-home-13__inner {
    display: flex;
    flex-direction: column;
    gap: 42px;
}

/* ── Header ──────────────────────────────────── */
.sec-5-home-13__header {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 32px;
}

.sec-5-home-13__title {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: clamp(48px, 5.5vw, 84px);
    line-height: 1;
    letter-spacing: -0.05em;
    color: var(--at-neutral-950);
}

.sec-5-home-13__hint {
    display: inline-flex;
    align-items: center;
    gap: 12px;
    font-family: var(--at-ff-body);
    font-weight: 500;
    font-size: 14px;
    line-height: 1.4;
    letter-spacing: -0.02em;
    color: var(--at-neutral-700);
    text-transform: uppercase;
    max-width: 600px;
}

.sec-5-home-13__hint-dot {
    width: 8px;
    height: 8px;
    background-color: var(--at-theme-primary);
    flex-shrink: 0;
}

/* ── List ────────────────────────────────────── */
.sec-5-home-13__list {
    display: flex;
    flex-direction: column;
    gap: 47px;
}

/* ── Card ────────────────────────────────────── */
.sec-5-home-13__card {
    display: grid;
    grid-template-columns: 583px 1fr;
    gap: 60px;
    background-color: var(--at-neutral-0);
    padding: 42px;
    align-items: center;
    border-radius: 4px;
}

.sec-5-home-13__card-media {
    width: 100%;
    height: 310px;
    overflow: hidden;

    img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
        transition: transform 0.6s ease;
    }

    .sec-5-home-13__card:hover & img {
        transform: scale(1.04);
    }
}

.sec-5-home-13__card-body {
    display: flex;
    flex-direction: column;
    gap: 20px;
    min-width: 0;
    padding-right: 16px;
}

.sec-5-home-13__card-head {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 24px;
    border-bottom: 1px solid var(--at-neutral-100);
    padding-bottom: 19px;
}

.sec-5-home-13__card-title {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 36px;
    line-height: 1;
    letter-spacing: -0.05em;
    color: var(--at-neutral-900);
}

.sec-5-home-13__card-tag {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    flex-shrink: 0;
}

.sec-5-home-13__card-tag-text {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 16px;
    line-height: 1;
    letter-spacing: -0.02em;
    color: var(--at-neutral-900);
    white-space: nowrap;
}

.sec-5-home-13__card-toggle {
    width: 18px;
    height: 18px;
    background: transparent;
    border: 0;
    padding: 0;
    color: var(--at-neutral-900);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: transform 0.3s ease, color 0.3s ease;

    &:hover,
    &:focus-visible {
        color: var(--at-theme-primary);
        transform: rotate(90deg);
    }
}

.sec-5-home-13__card-text {
    font-family: var(--at-ff-body);
    font-weight: 500;
    font-size: 22px;
    line-height: 1.45;
    letter-spacing: -0.05em;
    color: var(--at-neutral-500);
    max-width: 803px;
}

/* ── Responsive ──────────────────────────────── */
@media #{$xxl} {
    .sec-5-home-13 {
        padding: 96px 32px;
    }

    .sec-5-home-13__card {
        grid-template-columns: 460px 1fr;
        gap: 40px;
        padding: 32px;
    }

    .sec-5-home-13__card-media {
        height: 260px;
    }
}

@media #{$xl} {
    .sec-5-home-13 {
        padding: 80px 24px;
    }

    .sec-5-home-13__list {
        gap: 32px;
    }

    .sec-5-home-13__card {
        grid-template-columns: 380px 1fr;
        gap: 32px;
        padding: 24px;
    }

    .sec-5-home-13__card-media {
        height: 240px;
    }

    .sec-5-home-13__card-title {
        font-size: 28px;
    }

    .sec-5-home-13__card-text {
        font-size: 18px;
    }
}

@media #{$lg} {
    .sec-5-home-13 {
        padding: 64px 20px;
    }

    .sec-5-home-13__header {
        flex-direction: column;
        align-items: flex-start;
        gap: 16px;
    }

    .sec-5-home-13__card {
        grid-template-columns: 320px 1fr;
        gap: 24px;
        padding: 20px;
    }

    .sec-5-home-13__card-media {
        height: 220px;
    }

    .sec-5-home-13__card-head {
        flex-direction: column;
        align-items: flex-start;
        gap: 12px;
    }

    .sec-5-home-13__card-title {
        font-size: 24px;
    }
}

@media #{$md} {
    .sec-5-home-13 {
        padding: 48px 30px;
    }

    .sec-5-home-13__list {
        gap: 24px;
    }

    .sec-5-home-13__card {
        grid-template-columns: 1fr;
        padding: 20px;
    }

    .sec-5-home-13__card-media {
        height: 240px;
    }

    .sec-5-home-13__card-text {
        font-size: 16px;
    }
}

@media #{$sm} {
    .sec-5-home-13 {
        padding: 36px 30px;
    }

    .sec-5-home-13__card-media {
        height: 200px;
    }

    .sec-5-home-13__card-title {
        font-size: 22px;
    }

    .sec-5-home-13__card-tag-text {
        font-size: 13px;
    }
}

@media #{$xs} {
    .sec-5-home-13 {
        padding: 36px 30px;
    }

    .sec-5-home-13__card {
        padding: 16px;
    }

    .sec-5-home-13__card-media {
        height: 180px;
    }

    .sec-5-home-13__card-title {
        font-size: 20px;
    }

    .sec-5-home-13__card-text {
        font-size: 15px;
    }
}

/* Cascading mobile pivot: stack header + card-head for tablet & phone */
@media (max-width: 1199.98px) {
    .sec-5-home-13__header {
        flex-direction: column;
        align-items: flex-start;
        gap: 16px;
    }

    .sec-5-home-13__card-head {
        flex-direction: column;
        align-items: flex-start;
        gap: 12px;
    }
}

/* Cascading mobile pivot: single-column card layout for phone */
@media (max-width: 767.98px) {
    .sec-5-home-13__card {
        grid-template-columns: 1fr;
    }
}