@use '../../utils' as *;

/*------------------------------------------------------------------
  Home 8 — Section 8 (Testimonials)
------------------------------------------------------------------*/

.sec-8-home-8 {
    background: var(--at-neutral-50);
    padding-top: clamp(70px, 6vw, 130px);
    padding-bottom: clamp(70px, 6vw, 130px);

    &__container {
        padding-left: clamp(20px, 5.2vw, 102px);
        padding-right: clamp(20px, 5.2vw, 102px);
    }

    &__kicker {
        font-size: 16px;
        font-weight: 600;
        letter-spacing: -0.05em;
        text-transform: uppercase;
        color: var(--at-neutral-900);
        white-space: nowrap;
    }

    &__kicker-icon {
        width: 14px;
        height: 13px;
        display: inline-flex;
        align-items: center;
        justify-content: center;

        img {
            width: 100%;
            height: 100%;
            display: block;
        }
    }

    &__trusted {
        font-size: 16px;
        font-weight: 500;
        letter-spacing: -0.02em;
        color: var(--at-neutral-900);
        white-space: nowrap;
        text-underline-offset: 3px;
    }

    &__stage {
        position: relative;
        min-height: 1150px;
    }

    &__center {
        position: absolute;
        left: 50%;
        top: 50%;
        transform: translate(-50%, -58%);
        text-align: center;
        width: min(595px, 92vw);
    }

    &__asterisk {
        width: 122px;
        height: auto;
        display: block;
        margin: 0 auto 22px;
        transform-origin: 50% 50%;
    }

    &__title {
        font-size: clamp(44px, 4.375vw, 84px);
        font-weight: 600;
        line-height: 1;
        letter-spacing: -0.05em;
        color: var(--at-neutral-900);
    }

    &__group {
        position: absolute;
        width: 408px;
        display: flex;
        flex-direction: column;
        gap: 8px;
    }

    &__namebar {
        height: 88px;
        background: var(--at-neutral-0);
        border-radius: 16px;
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 0 45px;
        overflow: hidden;
    }

    &__name {
        font-size: 24px;
        font-weight: 600;
        letter-spacing: -0.05em;
        color: var(--at-neutral-900);
        white-space: nowrap;
    }

    &__plus {
        font-size: 24px;
        font-weight: 600;
        letter-spacing: -0.05em;
        color: var(--at-neutral-500);
        flex-shrink: 0;
    }

    &__card {
        height: 450px;
        background: var(--at-neutral-0);
        border-radius: 16px;
        position: relative;
        overflow: hidden;
    }

    &__role {
        position: absolute;
        top: 52px;
        right: 37px;
        text-align: right;
        font-size: 16px;
        font-weight: 500;
        letter-spacing: -0.02em;
        color: var(--at-neutral-900);
        line-height: 1.2;

        span {
            display: block;
        }
    }

    &__body {
        position: absolute;
        left: 48px;
        top: 117px;
        width: 323px;
        display: flex;
        flex-direction: column;
        gap: 32px;
    }

    &__avatar {
        width: 65px;
        height: 65px;
        border-radius: 8px;
        border: 4px solid var(--at-neutral-50);
        overflow: hidden;

        img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            display: block;
        }
    }

    &__quote {
        font-size: 20px;
        font-weight: 500;
        letter-spacing: -0.02em;
        color: var(--at-neutral-500);
        line-height: 1.4;
    }

    &__stars {
        position: absolute;
        left: 48px;
        bottom: 62px;
        display: flex;
        gap: 4px;

        img {
            width: 18px;
            height: 17px;
            display: block;
        }
    }

 // Desktop placements coordinates
    &__group--a {
        left: 0;
        top: 30px;
    }

    &__group--b {
        right: 0;
        top: 324px;
    }

    &__group--c {
        left: 145px;
        top: 827px;
    }

    &__group--d {
        left: 50%;
        top: 1028px;
    }



    @media (max-width: 1399px) {
        &__stage {
            min-height: auto;
        }

        &__center {
            position: static;
            transform: none;
            margin: 0 auto 40px;
        }

        &__group {
            position: static;
            width: 100%;
            max-width: 560px;
            margin: 0 auto 24px;
        }

        &__card {
            height: auto;
            padding: 40px 24px 90px;
        }

        &__role {
            position: static;
            text-align: left;
            margin-bottom: 18px;
        }

        &__body {
            position: static;
            width: auto;
        }

        &__stars {
            left: 24px;
            bottom: 32px;
        }
    }
}