@use '../../utils' as *;

/*----------------------------------------*/
/*  sec-8-home-15 (Home 15 — Testimonials)
/*----------------------------------------*/

.sec-8-home-15 {
    position: relative;
    padding-top: 100px;
    padding-bottom: 110px;
    border-bottom: 1px solid var(--at-neutral-200, #cdcccc);
    text-align: center;

    @media #{$xl} {
        padding-top: 88px;
        padding-bottom: 96px;
    }

    @media #{$lg}, #{$md} {
        padding-top: 72px;
        padding-bottom: 80px;
    }

    @media #{$sm}, #{$xs} {
        padding-top: 56px;
        padding-bottom: 64px;
    }

    /* ---- Eyebrow ---- */
    &__eyebrow {
        color: var(--at-neutral-900, #1d1d1d);
        margin-bottom: 56px;

        svg {
            flex-shrink: 0;
        }

        @media #{$lg}, #{$md} {
            margin-bottom: 44px;
        }

        @media #{$sm}, #{$xs} {
            margin-bottom: 32px;
        }
    }

    &__eyebrow-text {
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 16px;
        line-height: 1.2;
        letter-spacing: -0.05em;
    }

    /* ---- Main slider ---- */
    &__slider {
        max-width: 1330px;
        margin-left: auto;
        margin-right: auto;
        margin-bottom: 64px;

        @media #{$lg}, #{$md} {
            margin-bottom: 48px;
        }

        @media #{$sm}, #{$xs} {
            margin-bottom: 36px;
        }
    }

    &__slide {
        display: flex;
        align-items: center;
        justify-content: center;
    }

    &__quote {
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: clamp(22px, 3.4vw, 48px);
        line-height: 1.085;
        letter-spacing: -0.05em;
        color: var(--at-neutral-950, #0f0f0f);
        max-width: 1330px;
    }

    /* ---- Thumbs slider ---- */
    &__thumbs {
        max-width: 814px;
        margin-left: auto;
        margin-right: auto;

        .swiper-wrapper {
            align-items: center;
        }
    }

    &__thumb {
        flex-shrink: 0;
        height: auto;
        aspect-ratio: 1 / 1;
        padding: 0;
        background: transparent;
        border: 5px solid var(--at-neutral-50, #f2f2f2);
        cursor: pointer;
        overflow: hidden;
        transition: border-color 0.3s ease;

        &:hover {
            border-color: var(--at-neutral-200, #cdcccc);
        }

        &.swiper-slide-thumb-active {
            border-color: var(--at-theme-primary, #f0460e);
        }

        @media #{$md} {
            border-width: 4px;
        }

        @media #{$sm} {
            border-width: 4px;
        }

        @media #{$xs} {
            border-width: 3px;
        }
    }

    &__thumb-img {
        display: block;
        width: 100%;
        height: 100%;
        object-fit: cover;
        object-position: center;
    }
}
