@use '../../utils' as *;

/* Home 13 / Section 7 — Testimonial */
.sec-7-home-13 {
    background-color: var(--at-neutral-0);
    padding: 120px 96px;
}

.sec-7-home-13__inner {
    display: grid;
    grid-template-columns: 620px 1fr;
    gap: 64px;
    align-items: stretch;
}

/* ── Media ───────────────────────────────────── */
.sec-7-home-13__media {
    width: 100%;
    height: 760px;
    border-radius: 24px;
    overflow: hidden;
    background-color: var(--at-neutral-100);

    img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        display: block;
    }
}

.sec-7-home-13__media-slider {
    width: 100%;
    height: 100%;
    cursor: grab;

    &:active {
        cursor: grabbing;
    }

    .swiper-wrapper,
    .swiper-slide {
        height: 100%;
    }
}

.sec-7-home-13__quote-slider {
    width: 100%;
    cursor: grab;

    &:active {
        cursor: grabbing;
    }

    .swiper-slide {
        height: auto;
    }
}

/* ── Content ─────────────────────────────────── */
.sec-7-home-13__content {
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    gap: 32px;
    min-width: 0;

    @media (min-width: 1200px) {
        min-height: 760px;
    }
}

/* ── Head ────────────────────────────────────── */
.sec-7-home-13__head {
    display: flex;
    flex-direction: column;
    gap: 24px;
}

.sec-7-home-13__label {
    display: inline-flex;
    align-items: center;
    gap: 12px;
}

.sec-7-home-13__label-dot {
    width: 8px;
    height: 8px;
    background-color: var(--at-theme-primary);
    flex-shrink: 0;
}

.sec-7-home-13__label-text {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 16px;
    line-height: 1.2;
    letter-spacing: -0.05em;
    color: var(--at-neutral-900);
}

.sec-7-home-13__title {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: clamp(32px, 3.2vw, 56px);
    line-height: 1.143;
    letter-spacing: -0.03em;
    color: var(--at-neutral-950);
}

.sec-7-home-13__lede {
    font-family: var(--at-ff-body);
    font-weight: 500;
    font-size: 20px;
    line-height: 1.45;
    letter-spacing: -0.02em;
    color: var(--at-neutral-500);
    max-width: 773px;
}

/* ── Quote ───────────────────────────────────── */
.sec-7-home-13__quote {
    display: flex;
    flex-direction: column;
    gap: 24px;
    margin: 0;
}

.sec-7-home-13__quote-mark {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 96px;
    line-height: 0.65;
    color: var(--at-theme-primary);
    display: inline-block;
}

.sec-7-home-13__quote-text {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 22px;
    line-height: 1.45;
    letter-spacing: -0.02em;
    color: var(--at-neutral-950);
}

.sec-7-home-13__quote-foot {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    padding-top: 16px;
    flex-wrap: wrap;
}

.sec-7-home-13__author {
    display: inline-flex;
    align-items: center;
    gap: 16px;
}

.sec-7-home-13__author-name {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 18px;
    line-height: 1;
    letter-spacing: -0.02em;
    color: var(--at-neutral-950);
    font-style: normal;
}

.sec-7-home-13__author-sep {
    width: 24px;
    height: 1px;
    background-color: var(--at-neutral-500);
}

.sec-7-home-13__author-project {
    font-family: var(--at-ff-body);
    font-weight: 500;
    font-size: 14px;
    line-height: 1;
    letter-spacing: -0.02em;
    color: var(--at-neutral-500);
}

.sec-7-home-13__stars {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 0;
}

/* ── CTA ─────────────────────────────────────── */
.sec-7-home-13__cta {
    display: inline-flex;
    align-items: center;
    text-decoration: none;
    align-self: flex-start;
    transition: opacity 0.3s ease;

    &:hover,
    &:focus-visible {
        opacity: 0.85;
    }
}

.sec-7-home-13__cta-label {
    display: inline-flex;
    align-items: center;
    height: 50px;
    padding: 14px 27px;
    background-color: var(--at-neutral-0);
    border: 1px solid var(--at-neutral-100);
    color: var(--at-neutral-900);
    border-radius: 50px;
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 16px;
    letter-spacing: -0.05em;
    white-space: nowrap;
}

.sec-7-home-13__cta-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 50px;
    height: 50px;
    background-color: var(--at-neutral-0);
    border: 1px solid var(--at-neutral-100);
    color: var(--at-neutral-900);
    border-radius: 50%;
    margin-left: -1px;

    svg {
        transition: transform 0.3s ease;
    }
}

.sec-7-home-13__cta:hover .sec-7-home-13__cta-icon svg,
.sec-7-home-13__cta:focus-visible .sec-7-home-13__cta-icon svg {
    transform: rotate(-12deg);
}

/* ── Responsive ──────────────────────────────── */
@media #{$xxl} {
    .sec-7-home-13 {
        padding: 96px 32px;
    }
    .sec-7-home-13__inner {
        grid-template-columns: 480px 1fr;
        gap: 48px;
    }
    .sec-7-home-13__media,
    .sec-7-home-13__content {
        height: 640px;
        min-height: 640px;
    }
}

@media #{$xl} {
    .sec-7-home-13 {
        padding: 80px 24px;
    }
    .sec-7-home-13__inner {
        grid-template-columns: 400px 1fr;
        gap: 32px;
    }
    .sec-7-home-13__media,
    .sec-7-home-13__content {
        height: 560px;
        min-height: 560px;
    }
    .sec-7-home-13__quote-text {
        font-size: 18px;
    }
    .sec-7-home-13__lede {
        font-size: 18px;
    }
}

/* Stack inner as flex column on tablet & phone */
@media (max-width: 1199.98px) {
    .sec-7-home-13__inner {
        display: flex;
        flex-direction: column;
    }
}

@media #{$lg} {
    .sec-7-home-13 {
        padding: 64px 20px;
    }
    .sec-7-home-13__inner {
        gap: 32px;
    }
    .sec-7-home-13__media {
        height: 480px;
    }
    .sec-7-home-13__content {
        min-height: auto;
        height: auto;
        gap: 32px;
    }
}

@media #{$md} {
    .sec-7-home-13 {
        padding: 48px 30px;
    }
    .sec-7-home-13__media {
        height: 420px;
        border-radius: 16px;
    }
    .sec-7-home-13__title {
        font-size: 28px;
    }
    .sec-7-home-13__quote-mark {
        font-size: 72px;
    }
}

@media #{$sm} {
    .sec-7-home-13 {
        padding: 36px 30px;
    }
    .sec-7-home-13__media {
        height: 360px;
    }
    .sec-7-home-13__quote-foot {
        align-items: flex-start;
        flex-direction: column;
        gap: 16px;
    }
}

@media #{$xs} {
    .sec-7-home-13 {
        padding: 36px 30px;
    }
    .sec-7-home-13__media {
        height: 320px;
    }
    .sec-7-home-13__title {
        font-size: 24px;
    }
    .sec-7-home-13__quote-text {
        font-size: 16px;
    }
}
