@use '../../utils' as *;

/*----------------------------------------*/
/*  Footer style 9 (Home 9)
/*----------------------------------------*/

.footer-9 {
    position: relative;
    padding-top: clamp(48px, 5.5vw, 87px);
    padding-bottom: 0;
    background: var(--at-neutral-50, #f2f2f2);
    color: var(--at-neutral-950, #0f0f0f);

    &__container {
        max-width: 2200px;
        padding-left: clamp(20px, 5.2vw, 100px);
        padding-right: clamp(20px, 5.2vw, 100px);
    }

    &__top {
        margin-bottom: clamp(32px, 4vw, 56px);
    }

    &__label {
        margin: 0 0 clamp(18px, 2vw, 24px);
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: 12px;
        line-height: 1;
        letter-spacing: -0.02em;
        text-transform: uppercase;
        color: var(--at-neutral-950, #0f0f0f);
        opacity: 0.5;
    }

    /* Same structure / hover as footer-6 alt-footer-link-item; links stay neutral-950 on light bg */
    &__quick-links {
        margin-left: 0;
        margin-right: 0;

        .alt-footer-link-item ul li {
            list-style: none;

            a {
                display: inline-flex;
                align-items: center;
                font-family: var(--at-ff-body);
                font-weight: 400;
                font-size: clamp(17px, 1.25vw, 20px);
                line-height: 1.2;
                letter-spacing: -0.05em;
                color: var(--at-neutral-950, #0f0f0f);
                text-decoration: none;
                position: relative;
                transition: all 0.5s ease;

                &::before {
                    content: '';
                    width: 14px;
                    height: 13px;
                    background-image: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" width="14" height="13" viewBox="0 0 14 13" fill="none"><path d="M11.0037 3.41421L2.39712 12.0208L0.98291 10.6066L9.5895 2H2.00373V0H13.0037V11H11.0037V3.41421Z" fill="%230f0f0f"/></svg>');
                    margin-left: 14px;
                    position: absolute;
                    left: 100%;
                    top: 50%;
                    opacity: 0;
                    transition: all 0.5s ease;
                    transform: translate(-15px, -40%);
                }

                &:hover {
                    @include bgborder(currentColor, 0, 100%);
                    margin-left: 5px;
                    transition: all 0.5s ease;

                    &::before {
                        opacity: 0.85;
                        transform: translate(-50%, -50%);
                    }
                }
            }
        }
    }

    &__contact-row {
        display: flex;
        flex-wrap: wrap;
        gap: clamp(24px, 4vw, 48px);
        align-items: flex-start;
    }

    &__contact {
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: clamp(17px, 1.25vw, 20px);
        line-height: 1.45;
        letter-spacing: -0.02em;
        color: var(--at-neutral-950, #0f0f0f);

        a {
            color: inherit;
            text-decoration: none;
            transition: color 0.25s ease;

            &:hover {
                color: var(--at-theme-primary);
            }
        }
    }

    &__contact-line+&__contact-line {
        margin-top: 16px;
    }

    &__address {
        margin-top: 16px;
    }

    &__hours {
        &-label {
            margin-bottom: 6px;
            font-family: var(--at-ff-body);
            font-weight: 500;
            font-size: 12px;
            line-height: 1;
            letter-spacing: -0.02em;
            text-transform: uppercase;
            color: var(--at-neutral-950, #0f0f0f);
            opacity: 0.5;
        }

        &-value {
            font-family: var(--at-ff-body);
            font-weight: 500;
            font-size: clamp(17px, 1.25vw, 20px);
            line-height: 1.2;
            letter-spacing: -0.05em;
            color: var(--at-neutral-950, #0f0f0f);
        }
    }

    /* Same HTML pattern as footer-7 `.alt-footer-social-item`; neutral-950 text/icons on light bg */
    &__socials {
        max-width: 436px;
        margin-left: auto;
        padding-top: 4px;

        @media (max-width: 1199px) {
            margin-left: 0;
        }

        &.alt-footer-social-item.white-mode ul li a {
            color: var(--at-neutral-950, #0f0f0f);

            .icon-social {
                color: var(--at-neutral-950, #0f0f0f);
            }

            &>svg {
                flex-shrink: 0;
                color: var(--at-neutral-950, #0f0f0f);
            }

            /* Keep neutral-950 on hover (override white-mode neutral-900) */
            &:hover {
                color: var(--at-neutral-950, #0f0f0f);

                .icon-social,
                &>svg {
                    color: var(--at-neutral-950, #0f0f0f);
                }
            }
        }
    }

    &__brand {
        margin: 0 auto clamp(40px, 6vw, 80px);
        max-width: 100%;
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: clamp(42px, 12vw, 192px);
        line-height: 0.88;
        letter-spacing: -0.05em;
        text-align: center;
        color: var(--at-neutral-950, #0f0f0f);
    }

    &__bottom {
        padding-top: 24px;
    }

    &__bottom-bar {
        padding-bottom: clamp(20px, 2.5vw, 28px);
    }

    &__copy {
        font-family: var(--at-ff-body);
        font-size: 16px;
        font-weight: 500;
        line-height: 1;
        letter-spacing: -0.02em;
        color: var(--at-neutral-500, #585959);
    }

    &__policies {
        a {
            font-family: var(--at-ff-body);
            font-size: 16px;
            font-weight: 500;
            line-height: 1;
            letter-spacing: -0.02em;
            color: var(--at-neutral-500, #585959);
            text-decoration: none;
            white-space: nowrap;
            transition: color 0.25s ease;

            &:hover {
                color: var(--at-neutral-950, #0f0f0f);
            }
        }
    }

    &__line {
        width: 100%;
        max-width: 1720px;
        margin: 0 auto;

        img {
            display: block;
            width: 100%;
            height: auto;
        }
    }
}