@use '../../utils' as *;

/*----------------------------------------*/
/*  sec-4-home-9 (Home 9 — Selected work)
/*----------------------------------------*/

.sec-4-home-9 {
    position: relative;
    padding-top: clamp(48px, 4.2vw, 80px);
    padding-bottom: clamp(60px, 6.5vw, 130px);
    border-top: 1px solid var(--at-neutral-200, #cdcccc);

    &__container {
        max-width: 2200px;
        margin: 0 auto;
        padding-left: clamp(20px, 5.2vw, 100px);
        padding-right: clamp(20px, 5.2vw, 100px);
    }

    &__title {
        margin: 0 auto clamp(28px, 3vw, 48px);
        max-width: 100%;
        font-family: var(--at-ff-heading);
        font-weight: 800;
        font-size: clamp(52px, 10.3vw, 198px);
        line-height: 0.95;
        letter-spacing: -0.07em;
        text-align: center;
        text-transform: uppercase;
        color: var(--at-neutral-950, #0f0f0f);
    }

    &__filters {
        margin-bottom: clamp(36px, 3.6vw, 72px);

        .at-btn.filter-btn {
            padding: 12px 24px;
            font-size: 16px;
            letter-spacing: -0.05em;
        }
    }

    &__grid {
        --sec4-gap: clamp(20px, 1.56vw, 30px);
        display: grid;
        gap: var(--sec4-gap);
        grid-template-columns: 1fr;

        @media (min-width: 992px) {
            grid-template-columns: repeat(2, minmax(0, 1fr));
            align-items: start;
        }
    }

    &__col {
        display: flex;
        flex-direction: column;
        gap: var(--sec4-gap);
        min-width: 0;
    }

    @media #{$lg} {
        &__col--offset {
            margin-top: -20px;
        }
    }

    &__card {
        display: flex;
        flex-direction: column;
        gap: 8px;
    }

    &__visual {
        position: relative;
        border-radius: 16px;
        overflow: hidden;
        background: var(--at-neutral-0, #fefefe);
        aspect-ratio: 845 / 542;
    }

    &__visual-link {
        display: block;
        position: relative;
        width: 100%;
        height: 100%;
        color: inherit;
        text-decoration: none;

        img {
            display: block;
            width: 100%;
            height: 100%;
            object-fit: cover;
        }
    }

    &__badge {
        position: absolute;
        top: clamp(16px, 1.2vw, 23px);
        right: clamp(16px, 1.2vw, 23px);
        z-index: 2;
        padding: 8px 10px;
        border-radius: 20px;
        background: var(--at-theme-primary, #f0460e);
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 10px;
        line-height: 1;
        letter-spacing: -0.02em;
        text-transform: uppercase;
        color: var(--at-neutral-0, #fefefe);
        pointer-events: none;
    }

    &__overlay {
        position: absolute;
        left: 0;
        right: 0;
        bottom: 0;
        min-height: 49.5%;
        padding: clamp(28px, 2.8vw, 45px) clamp(24px, 2.8vw, 53px);
        display: flex;
        flex-direction: column;
        align-items: flex-start;
        justify-content: flex-end;
        gap: clamp(14px, 1.15vw, 22px);
        background: linear-gradient(180deg, rgba(26, 26, 26, 0) 11.9%, rgba(26, 26, 26, 0.76) 100%);
        pointer-events: none;
    }

    &__tag {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        padding: 10.5px 19px;
        border-radius: 32px;
        border: 1px solid var(--at-neutral-100, #dfdfdf);
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 12px;
        line-height: 1;
        letter-spacing: -0.02em;
        text-transform: uppercase;
        color: var(--at-neutral-0, #fefefe);
    }

    &__metric {
        margin: 0;
        max-width: 100%;
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: clamp(28px, 2.5vw, 48px);
        line-height: 1.08;
        letter-spacing: -0.05em;
        color: var(--at-neutral-0, #fefefe);
    }

    &__excerpt {
        margin: 0;
        max-width: min(473px, 100%);
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: clamp(16px, 1.05vw, 20px);
        line-height: 1.35;
        letter-spacing: -0.02em;
        color: var(--at-neutral-0, #fefefe);
    }

    &__bar {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        min-height: 88px;
        padding: 16px clamp(24px, 2.35vw, 45px);
        border-radius: 16px;
        background: var(--at-neutral-0, #fefefe);
    }

    &__project {
        margin: 0;
        flex: 1;
        min-width: 0;
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: clamp(22px, 1.9vw, 36px);
        line-height: 1.1;
        letter-spacing: -0.05em;
        color: var(--at-neutral-900, #1d1d1d);
    }

    &__case {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        flex-shrink: 0;
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 12px;
        line-height: 1;
        letter-spacing: -0.02em;
        text-transform: uppercase;
        text-decoration: none;
        color: var(--at-neutral-900, #1d1d1d);
        transition: color 0.25s ease;

        img {
            display: block;
            width: 12px;
            height: auto;
        }

        &:hover {
            color: var(--at-theme-primary);
        }
    }

    &__cta {
        margin-top: clamp(40px, 4vw, 72px);
        margin-left: auto;
        max-width: 627px;
        display: flex;
        flex-direction: column;
        align-items: flex-start;
        gap: clamp(20px, 1.56vw, 30px);
    }

    &__cta-text {
        margin: 0;
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: clamp(22px, 1.9vw, 36px);
        line-height: 1.25;
        letter-spacing: -0.05em;
        color: var(--at-neutral-950, #0f0f0f);
    }

    &__cta-btn {
        display: inline-flex;
        align-items: center;
        gap: 12px;
        height: 50px;
        padding: 14px 27px;
        border-radius: 50px;
        border: none;
        background: #1d1d1d;
        color: #fefefe !important;
        font-family: var(--at-ff-body);
        font-weight: 600;
        font-size: 16px;
        letter-spacing: -0.05em;
        text-transform: none;
        text-decoration: none;
        transition: background 0.25s ease, color 0.25s ease;

        img {
            display: block;
            flex-shrink: 0;
        }

        &:hover {
            background: var(--at-theme-primary);
            color: var(--at-neutral-0) !important;
        }
    }
}
