@use '../../utils' as *;

/*----------------------------------------*/
/*  Portfolio Details 5 — Swiper Fade + Cinematic
/*  Brand accent: var(--at-theme-primary) (#F0460E)
/*----------------------------------------*/

/* JS injects `.anim-zoomin-wrap` around every `.anim-zoomin` <img>.
   Image hosts use absolute-fill img inside aspect-ratio box. */
.sec-4-portfolio-details-5__cell,
.sec-7-portfolio-details-5__media {
    .anim-zoomin-wrap {
        position: absolute;
        inset: 0;
        overflow: hidden;
    }
}

/* =========================================================
   SEC 1 — Swiper fade hero (full-bleed)
   ========================================================= */
.sec-1-portfolio-details-5 {
    position: relative;
    height: 820px;
    background: var(--at-neutral-950);
    color: var(--at-neutral-0);

    &__slider {
        position: absolute;
        inset: 0;
        height: 100%;
        width: 100%;
        z-index: 0;

        .swiper-wrapper,
        .swiper-slide {
            height: 100%;
        }
    }

    &__slide {
        position: relative;
        overflow: hidden;

        img {
            position: absolute;
            inset: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
        }
    }

    &__veil {
        position: absolute;
        left: 0;
        right: 0;
        pointer-events: none;
        z-index: 1;

        &--top {
            top: 0;
            height: 100%;
            background: rgba(15, 15, 15, 0.35);
        }

        &--bottom {
            bottom: 0;
            height: 240px;
            background: linear-gradient(180deg, rgba(15, 15, 15, 0) 0%, rgba(15, 15, 15, 0.55) 100%);
        }
    }

    &__content {
        position: absolute;
        left: 0;
        right: 0;
        top: 50%;
        transform: translateY(-58%);
        z-index: 2;
    }

    &__eyebrow {
        color: var(--at-theme-primary);
        letter-spacing: 0.15em;
    }

    &__title {
        color: var(--at-neutral-0);
        letter-spacing: -0.05em;
        justify-content: center;

        sup {
            margin-left: 4px;
            line-height: 1;
        }
    }

    &__tagline {
        color: var(--at-neutral-100);
        letter-spacing: -0.03em;
    }

    /* Controls bar at the bottom of hero */
    &__controls {
        position: absolute;
        left: 0;
        right: 0;
        bottom: 40px;
        z-index: 3;
    }

    &__counter {
        display: inline-flex;
        align-items: baseline;
        gap: 6px;
        color: var(--at-neutral-0);
    }

    &__counter-num {
        font-size: 48px;
        line-height: 1;
        letter-spacing: -0.03em;
    }

    &__counter-total {
        font-size: 18px;
        opacity: 0.65;
        letter-spacing: -0.02em;
    }

    &__pagination {
        display: flex;
        justify-content: center;
        align-items: center;
        gap: 12px;

        /* Swiper bullets injected here */
        .swiper-pagination-bullet {
            width: 60px;
            height: 3px;
            border-radius: 2px;
            background: var(--at-neutral-0);
            opacity: 0.3;
            transition: background 0.3s ease, opacity 0.3s ease;
        }

        .swiper-pagination-bullet-active {
            background: var(--at-theme-primary);
            opacity: 1;
        }
    }

    &__nav {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 56px;
        height: 56px;
        border-radius: 50%;
        border: 1px solid rgba(254, 254, 254, 0.4);
        background: transparent;
        color: var(--at-neutral-0);
        cursor: pointer;
        transition: transform 0.3s ease, background-color 0.3s ease, border-color 0.3s ease;

        &:hover {
            transform: translateY(-2px);
        }

        &--next {
            background: var(--at-theme-primary);
            border-color: var(--at-theme-primary);

            &:hover {
                background: var(--at-neutral-0);
                color: var(--at-theme-primary);
                border-color: var(--at-neutral-0);
            }
        }

        &--prev:hover {
            background: var(--at-neutral-0);
            color: var(--at-neutral-950);
            border-color: var(--at-neutral-0);
        }
    }

    @media #{$lg} {
        height: 720px;
    }

    @media #{$md} {
        height: 620px;

        &__controls {
            bottom: 30px;
        }

        &__counter-num {
            font-size: 40px;
        }

        &__nav {
            width: 48px;
            height: 48px;
        }
    }

    @media #{$sm,$xs} {
        height: 560px;

        &__content {
            transform: translateY(-50%);
        }

        &__controls {
            bottom: 24px;
        }

        &__counter-num {
            font-size: 32px;
        }

        &__counter-total {
            font-size: 14px;
        }

        &__nav {
            width: 44px;
            height: 44px;
        }
    }

    @media #{$xs} {
        height: 520px;

        &__title {
            font-size: 60px !important;
        }
    }
}

/* =========================================================
   SEC 2 — Project brief strip
   ========================================================= */
.sec-2-portfolio-details-5 {
    background: var(--at-neutral-0);

    &__meta-row {
        border-top: 1px solid var(--at-neutral-100);
        border-bottom: 1px solid var(--at-neutral-100);
        margin: 0;
    }

    &__meta-cell {
        padding: 24px 24px;
        position: relative;

        & + & {
            border-left: 1px solid var(--at-neutral-100);
        }
    }

    &__lead {
        font-size: 30px;
        line-height: 1.4;
        letter-spacing: -0.04em;
    }

    &__chips {
        gap: 10px;
    }

    &__chip {
        padding: 10px 20px;
        background: var(--at-neutral-50);
        color: var(--at-neutral-900);
        border-radius: 25px;
        letter-spacing: 0.05em;
    }

    @media #{$md} {
        padding-top: 60px;
        padding-bottom: 70px;

        &__meta-cell {
            padding: 18px 18px;

            &:nth-child(3) {
                border-left: 0;
                border-top: 1px solid var(--at-neutral-100);
            }
            &:nth-child(4) {
                border-top: 1px solid var(--at-neutral-100);
            }
        }

        &__lead {
            font-size: 26px;
        }
    }

    @media #{$sm,$xs} {
        padding-top: 50px;
        padding-bottom: 60px;

        &__meta-cell {
            padding: 16px 12px;

            &:nth-child(2) {
                border-left: 1px solid var(--at-neutral-100);
            }

            &:nth-child(3),
            &:nth-child(4) {
                border-top: 1px solid var(--at-neutral-100);
            }

            &:nth-child(4) {
                border-left: 1px solid var(--at-neutral-100);
            }
        }

        &__lead {
            font-size: 22px;
            margin-top: 50px !important;
            margin-bottom: 50px !important;
        }
    }
}

/* =========================================================
   SEC 3 — Services + Stats (2-col)
   ========================================================= */
.sec-3-portfolio-details-5 {
    background: var(--at-neutral-50);

    &__eyebrow {
        color: var(--at-theme-primary);
        letter-spacing: 0.1em;
    }

    &__heading {
        font-size: 48px;
        letter-spacing: -0.05em;
        line-height: 1.15;
    }

    &__intro {
        line-height: 1.6;
        letter-spacing: -0.02em;
    }

    &__services {
        padding: 0;
    }

    &__service {
        display: flex;
        align-items: baseline;
        gap: 24px;
        padding: 18px 0;
        border-top: 1px solid var(--at-neutral-200);

        &:last-child {
            border-bottom: 1px solid var(--at-neutral-200);
        }
    }

    &__service-num {
        color: var(--at-theme-primary);
        flex: 0 0 60px;
    }

    &__service-title {
        letter-spacing: -0.03em;
    }

    &__stats {
        padding: 0;
    }

    &__stat {
        padding: 24px 0;
        border-top: 1px solid var(--at-neutral-950);

        &:last-child {
            border-bottom: 1px solid var(--at-neutral-950);
        }
    }

    &__stat-num {
        font-size: 88px;
        letter-spacing: -0.05em;
        color: var(--at-theme-primary);
        margin-bottom: 16px;
    }

    &__stat-desc {
        line-height: 1.5;
        letter-spacing: -0.02em;
    }

    @media #{$lg} {
        &__heading {
            font-size: 40px;
        }

        &__stat-num {
            font-size: 72px;
        }
    }

    @media #{$md} {
        padding-top: 70px;
        padding-bottom: 70px;

        &__heading {
            font-size: 36px;
        }

        &__stat-num {
            font-size: 64px;
        }
    }

    @media #{$sm,$xs} {
        padding-top: 60px;
        padding-bottom: 60px;

        &__heading {
            font-size: 30px;
        }

        &__stat-num {
            font-size: 56px;
        }
    }

    @media #{$xs} {
        &__heading {
            font-size: 26px;
        }

        &__service {
            gap: 16px;
            padding: 14px 0;
        }

        &__service-num {
            flex: 0 0 40px;
        }

        &__stat-num {
            font-size: 48px;
        }
    }
}

/* =========================================================
   SEC 4 — Image grid asymmetric (magazine)
   ========================================================= */
.sec-4-portfolio-details-5 {
    background: var(--at-neutral-0);

    &__row {
        display: grid;
        gap: 20px;
        margin-bottom: 20px;

        &:last-child {
            margin-bottom: 0;
        }

        &--a {
            grid-template-columns: 1fr 2fr;
        }

        &--b {
            grid-template-columns: 2fr 1fr;
        }
    }

    &__cell {
        position: relative;
        margin: 0;
        aspect-ratio: 7 / 5;
        overflow: hidden;
        border-radius: 6px;
        background: var(--at-neutral-100);

        img {
            position: absolute;
            inset: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.8s ease;
        }

        &:hover img {
            transform: scale(1.05);
        }
    }

    @media #{$md} {
        padding-top: 60px;
        padding-bottom: 60px;

        &__row {
            gap: 16px;
            margin-bottom: 16px;
        }
    }

    @media #{$sm,$xs} {
        padding-top: 50px;
        padding-bottom: 50px;

        &__row {
            grid-template-columns: 1fr !important;
            gap: 12px;
            margin-bottom: 12px;
        }

        &__cell {
            aspect-ratio: 4 / 3;
        }
    }
}

/* =========================================================
   SEC 5 — Vertical timeline alternating L/R
   ========================================================= */
.sec-5-portfolio-details-5 {
    background: var(--at-neutral-0);

    &__eyebrow {
        color: var(--at-theme-primary);
        letter-spacing: 0.1em;
    }

    &__heading {
        font-size: 54px;
        letter-spacing: -0.05em;
        line-height: 1.15;
    }

    &__timeline {
        position: relative;
        padding: 30px 0;

        /* Center vertical line (desktop only) */
        &::before {
            content: '';
            position: absolute;
            top: 0;
            bottom: 0;
            left: 50%;
            width: 1px;
            background: var(--at-neutral-200);
            transform: translateX(-50%);
        }
    }

    &__step {
        position: relative;
        width: 50%;
        padding-bottom: 70px;

        &:last-child {
            padding-bottom: 0;
        }

        &--left {
            padding-right: 60px;
            text-align: right;
        }

        &--right {
            margin-left: 50%;
            padding-left: 60px;
            text-align: left;
        }
    }

    &__step-dot {
        position: absolute;
        top: 8px;
        width: 14px;
        height: 14px;
        background: var(--at-theme-primary);
        border-radius: 50%;
        border: 3px solid var(--at-neutral-0);
        box-shadow: 0 0 0 1px var(--at-neutral-200);
        z-index: 1;
    }

    &__step--left &__step-dot {
        right: -7px;
    }

    &__step--right &__step-dot {
        left: -7px;
    }

    &__step-body {
        max-width: 580px;
    }

    &__step--left &__step-body {
        margin-left: auto;
    }

    &__step-num {
        font-size: 64px;
        color: var(--at-theme-primary);
        letter-spacing: -0.04em;
    }

    &__step-title {
        letter-spacing: -0.03em;
    }

    &__step-desc {
        line-height: 1.55;
        letter-spacing: -0.02em;
    }

    @media #{$lg} {
        &__heading {
            font-size: 44px;
        }

        &__step-num {
            font-size: 56px;
        }
    }

    @media #{$md} {
        padding-top: 80px;
        padding-bottom: 80px;

        &__heading {
            font-size: 38px;
        }

        &__step-num {
            font-size: 48px;
        }

        &__timeline {
            &::before {
                left: 20px;
                transform: none;
            }
        }

        &__step {
            width: 100%;
            margin-left: 0 !important;
            padding-left: 60px !important;
            padding-right: 0 !important;
            text-align: left !important;

            &-dot {
                left: 14px !important;
                right: auto !important;
            }

            &-body {
                margin-left: 0 !important;
                max-width: none;
            }
        }
    }

    @media #{$sm,$xs} {
        padding-top: 60px;
        padding-bottom: 60px;

        &__heading {
            font-size: 30px;
        }

        &__step-num {
            font-size: 40px;
        }

        &__timeline {
            &::before {
                left: 14px;
                transform: none;
            }
        }

        &__step {
            width: 100%;
            margin-left: 0 !important;
            padding-left: 44px !important;
            padding-right: 0 !important;
            padding-bottom: 50px;
            text-align: left !important;

            &-dot {
                left: 8px !important;
                right: auto !important;
            }

            &-body {
                margin-left: 0 !important;
                max-width: none;
            }
        }
    }

    @media #{$xs} {
        &__heading {
            font-size: 26px;
        }
    }
}

/* =========================================================
   SEC 6 — Awards & Recognition (dark)
   ========================================================= */
.sec-6-portfolio-details-5 {
    background: var(--at-neutral-950);
    color: var(--at-neutral-0);

    &__eyebrow {
        color: var(--at-theme-primary);
        letter-spacing: 0.1em;
    }

    &__heading {
        color: var(--at-neutral-0);
        font-size: 54px;
        letter-spacing: -0.05em;
        line-height: 1.15;
    }

    &__list {
        border-top: 1px solid var(--at-neutral-700);
    }

    &__row {
        border-bottom: 1px solid var(--at-neutral-700);
    }

    &__link {
        display: grid;
        grid-template-columns: 120px 1fr 320px 60px;
        align-items: center;
        gap: 24px;
        padding: 28px 0;
        color: var(--at-neutral-0);
        text-decoration: none;
        transition: padding 0.35s ease, background-color 0.35s ease;

        &:hover {
            color: var(--at-neutral-0);
            padding-left: 16px;
            padding-right: 16px;
            background: rgba(254, 254, 254, 0.03);

            .sec-6-portfolio-details-5__arrow {
                transform: translate(4px, -4px);
            }
        }
    }

    &__year {
        color: var(--at-neutral-0);
        opacity: 0.6;
        letter-spacing: 0.1em;
    }

    &__title {
        font-size: 32px;
        letter-spacing: -0.04em;
    }

    &__org {
        color: var(--at-neutral-0);
        opacity: 0.75;
        letter-spacing: -0.02em;
        text-align: right;
    }

    &__arrow {
        color: var(--at-theme-primary);
        font-size: 22px;
        text-align: right;
        transition: transform 0.35s ease;
        display: inline-block;
    }

    @media #{$lg} {
        &__heading {
            font-size: 44px;
        }

        &__title {
            font-size: 28px;
        }

        &__link {
            grid-template-columns: 100px 1fr 220px 50px;
        }
    }

    @media #{$md} {
        padding-top: 70px;
        padding-bottom: 70px;

        &__heading {
            font-size: 38px;
        }

        &__title {
            font-size: 24px;
        }

        &__link {
            grid-template-columns: 80px 1fr auto 40px;
            gap: 16px;
        }

        &__org {
            font-size: 14px;
        }
    }

    @media #{$sm,$xs} {
        padding-top: 60px;
        padding-bottom: 60px;

        &__heading {
            font-size: 30px;
        }

        &__title {
            font-size: 20px;
        }

        &__link {
            grid-template-columns: 70px 1fr 30px;
            gap: 12px;
            padding: 20px 0;
        }

        &__org {
            display: none;
        }

        &__arrow {
            font-size: 18px;
        }
    }

    @media #{$xs} {
        &__heading {
            font-size: 26px;
        }

        &__title {
            font-size: 18px;
        }

        &__link {
            grid-template-columns: 56px 1fr 24px;
            gap: 10px;
        }
    }
}

/* =========================================================
   SEC 7 — Next project side-by-side (light)
   ========================================================= */
.sec-7-portfolio-details-5 {
    background: var(--at-neutral-0);

    &__group {
        text-decoration: none;
        color: inherit;
        display: block;

        &:hover {
            color: inherit;

            .sec-7-portfolio-details-5__cta span {
                transform: translate(4px, -4px);
            }
        }
    }

    &__eyebrow {
        color: var(--at-theme-primary);
        letter-spacing: 0.15em;
    }

    &__name {
        font-size: 200px;
        line-height: 0.95;
        letter-spacing: -0.05em;
    }

    &__tagline {
        letter-spacing: -0.03em;
        line-height: 1.4;
    }

    &__meta {
        letter-spacing: 0.1em;
    }

    &__cta {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        position: relative;
        padding-bottom: 6px;
        border-bottom: 1px solid var(--at-neutral-950);

        span {
            display: inline-block;
            transition: transform 0.35s ease;
        }
    }

    &__media {
        position: relative;
        width: 100%;
        aspect-ratio: 4 / 5;
        overflow: hidden;
        border-radius: 8px;
        background: var(--at-neutral-100);

        img {
            position: absolute;
            inset: 0;
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.8s ease;
        }

        &:hover img {
            transform: scale(1.04);
        }
    }

    @media #{$lg} {
        &__name {
            font-size: 140px;
        }
    }

    @media #{$md} {
        padding-top: 80px;
        padding-bottom: 80px;

        &__name {
            font-size: 110px;
        }

        &__media {
            aspect-ratio: 4 / 5;
            max-width: 500px;
        }
    }

    @media #{$sm,$xs} {
        padding-top: 60px;
        padding-bottom: 80px;

        &__name {
            font-size: 80px;
        }

        &__tagline {
            font-size: 18px;
        }

        &__media {
            aspect-ratio: 4 / 5;
            margin-top: 30px;
        }
    }

    @media #{$xs} {
        &__name {
            font-size: 60px;
        }
    }
}
