@use '../../utils' as *;

/*----------------------------------------*/
/*  sec-6-home-9 (Home 9 — Meet our team)
/*----------------------------------------*/

.sec-6-home-9 {
    position: relative;
    padding-top: clamp(56px, 6vw, 120px);
    padding-bottom: clamp(64px, 7vw, 160px);

    &__container {
        max-width: 2200px;
        margin: 0 auto;
        padding-left: clamp(20px, 5.2vw, 100px);
        padding-right: clamp(20px, 5.2vw, 100px);
    }

    &__header {
        text-align: center;
        max-width: 1100px;
        margin: 0 auto clamp(40px, 5vw, 88px);
    }

    &__tag {
        display: inline-flex;
        align-items: center;
        gap: 6px;
        margin-bottom: clamp(20px, 2.5vw, 38px);
    }

    &__tag-text {
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: 16px;
        line-height: 1;
        letter-spacing: -0.05em;
        text-transform: uppercase;
        color: var(--at-neutral-900, #1d1d1d);
    }

    &__title {
        margin: 0;
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: clamp(48px, 8.6vw, 124px);
        line-height: 1;
        letter-spacing: -0.05em;
        color: var(--at-neutral-950, #0f0f0f);
    }

    &__title-accent {
        color: var(--at-neutral-950, #0f0f0f);
    }

    &__body {
        position: relative;
    }

    &__list {
        position: relative;
        display: flex;
        flex-direction: column;
        gap: 16px;
        max-width: 1718px;
        margin: 0 auto;
    }

    &__card {
        @media (min-width: 768px) {
            cursor: pointer;
        }

        display: grid;
        gap: clamp(16px, 2vw, 24px);
        align-items: center;
        padding: clamp(16px, 2vw, 20px) clamp(20px, 3vw, 42px);
        border: 1px solid var(--at-neutral-100, #dfdfdf);
        background: var(--at-neutral-0, #fefefe);
        border-radius: 0;
        transition: all 0.3s ease;

        @media (min-width: 992px) {
            grid-template-columns: minmax(0, 1.1fr) minmax(0, 0.95fr) minmax(0, 1.1fr);
            gap: clamp(20px, 2vw, 32px);
        }

        @media (hover: hover) and (pointer: fine) {
            &:hover {
                border-radius: 24px;
                padding: clamp(16px, 2vw, 20px) clamp(30px, 5vw, 52px);
                transition: all 0.3s ease;
            }
        }

        &--accent {
            border-color: var(--at-neutral-200, #cdcccc);
        }
    }

    &__quote {
        margin: 0;
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: 16px;
        line-height: 1.35;
        letter-spacing: -0.02em;
        text-transform: uppercase;
        color: var(--at-neutral-800, #212121);
    }

    &__person {
        display: flex;
        align-items: center;
        gap: 16px;
    }

    &__avatar {
        flex-shrink: 0;
        width: 68px;
        height: 68px;
        border-radius: 100px;
        overflow: hidden;
        background: var(--at-neutral-100, #dfdfdf);

        img {
            display: block;
            width: 100%;
            height: 100%;
            object-fit: cover;
        }
    }

    &__meta {
        min-width: 0;
    }

    &__name {
        margin: 0 0 4px;
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: clamp(26px, 2.5vw, 36px);
        line-height: 1.1;
        letter-spacing: -0.05em;
        color: var(--at-neutral-900, #1d1d1d);
    }

    &__role {
        margin: 0;
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: 16px;
        line-height: 1.2;
        letter-spacing: -0.02em;
        text-transform: uppercase;
        color: var(--at-neutral-500, #585959);
    }

    &__skills {
        margin: 0;
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: 16px;
        line-height: 1.35;
        letter-spacing: -0.02em;
        text-transform: uppercase;
        color: var(--at-neutral-800, #212121);

        @media (min-width: 992px) {
            text-align: right;
            justify-self: end;
        }
    }

    &__footer {
        display: grid;
        gap: clamp(32px, 4vw, 48px);
        max-width: 1100px;
        margin: clamp(48px, 6vw, 100px) auto 0;

        @media (min-width: 768px) {
            grid-template-columns: 1fr 1fr;
            align-items: start;
        }
    }

    &__footer-primary {
        display: flex;
        gap: 24px;
        align-items: flex-start;
    }

    &__footer-icon {
        flex-shrink: 0;

        img {
            display: block;
            width: 40px;
            height: auto;
        }
    }

    &__footer-heading {
        margin: 0 0 18px;
        font-family: var(--at-ff-heading);
        font-weight: 600;
        font-size: 24px;
        line-height: 1.2;
        letter-spacing: -0.05em;
        color: var(--at-neutral-900, #1d1d1d);
    }

    &__footer-lines {
        font-family: var(--at-ff-body);
        font-weight: 500;
        font-size: 16px;
        line-height: 1.5;
        letter-spacing: -0.02em;
        color: var(--at-neutral-500, #585959);

        p {
            margin: 0 0 0.35em;
            color: inherit;

            &:last-child {
                margin-bottom: 0;
            }
        }
    }

    &__footer-secondary {
        @media (min-width: 768px) {
            margin-top: 44px;
        }
    }

    &__footer-link {
        color: var(--at-neutral-900, #1d1d1d);
        text-decoration: none;
        transition: color 0.2s ease;

        &:hover {
            color: var(--at-theme-primary);
        }
    }
}