@use '../../utils' as *;

/* Home 12 / Section 5 — Pricing */
.sec-5-home-12 {
    background-color: var(--at-neutral-50);
    padding-top: 120px;
    padding-bottom: 120px;
    position: relative;
    overflow: hidden;
}

/* ── Dot pattern background ─────────────────────── */
.sec-5-home-12__dots {
    position: absolute;
    inset: 0;
    pointer-events: none;
    opacity: 0.18;
    background-image:
        radial-gradient(circle, rgba(0, 0, 0, 0.45) 1.2px, transparent 1.4px),
        radial-gradient(circle, rgba(0, 0, 0, 0.45) 1.2px, transparent 1.4px);
    background-size: 96px 96px, 96px 96px;
    background-position: 0 0, 48px 48px;
}

/* ── Section header ─────────────────────────────── */
.sec-5-home-12__header {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    row-gap: 16px;
    margin-bottom: 64px;
}

.sec-5-home-12__eyebrow {
    margin: 0;
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 12px;
    line-height: 1;
    letter-spacing: 0.96px;
    color: var(--at-neutral-500);
    text-transform: uppercase;
}

.sec-5-home-12__title {
    margin: 0;
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: clamp(36px, 5vw, 64px);
    line-height: 1.125;
    letter-spacing: -0.05em;
    color: var(--at-neutral-950);
}

/* ── Tables row ─────────────────────────────────── */
.sec-5-home-12__tables {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 30px;
    max-width: 1287px;
    margin-inline: auto;
    margin-bottom: 64px;
}

/* ── Pricing card ───────────────────────────────── */
.card-home-12-price {
    position: relative;
    background-color: var(--at-neutral-0);
    border-radius: 16px;
    overflow: hidden;
    display: flex;
    flex-direction: column;
}

.card-home-12-price__top {
    position: relative;
    background-color: var(--at-neutral-50);
    border-radius: 14px;
    margin: 16px 16px 0;
    padding: 25px 29px 32px;
    min-height: 289px;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    row-gap: 7px;
}

.card-home-12-price.is-popular .card-home-12-price__top {
    background-color: rgba(240, 70, 14, 0.1);
}

.card-home-12-price__badge {
    position: absolute;
    top: 23px;
    right: 25px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 8px 10px;
    border-radius: 20px;
    background-color: var(--at-theme-primary);
    color: var(--at-neutral-0);
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 10px;
    line-height: 1;
    letter-spacing: -0.02em;
    text-transform: uppercase;
    white-space: nowrap;
}

.card-home-12-price__plan {
    margin: 0;
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 18px;
    line-height: 1;
    letter-spacing: -0.05em;
    color: var(--at-neutral-900);
    text-transform: capitalize;
}

.card-home-12-price__price {
    display: flex;
    align-items: flex-end;
    column-gap: 0;
}

.card-home-12-price__amount {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 48px;
    line-height: 52px;
    letter-spacing: -0.05em;
    color: var(--at-neutral-900);
}

.card-home-12-price__period {
    font-family: var(--at-ff-heading);
    font-weight: 500;
    font-size: 16px;
    line-height: 1.4;
    letter-spacing: -0.02em;
    color: var(--at-neutral-500);
    align-self: flex-end;
    padding-bottom: 4px;
}

.card-home-12-price__desc {
    margin: 24px 0 0;
    font-family: var(--at-ff-heading);
    font-weight: 500;
    font-size: 16px;
    line-height: 1.45;
    letter-spacing: -0.02em;
    color: var(--at-neutral-500);
    max-width: 100%;
}

.card-home-12-price__cta {
    margin-top: auto;
    align-self: flex-start;
    display: inline-flex;
    align-items: center;
    column-gap: 12px;
    height: 50px;
    padding: 14px 42px;
    border-radius: 50px;
    background-color: var(--at-neutral-900);
    color: var(--at-neutral-0);
    text-decoration: none;
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 16px;
    line-height: 1;
    letter-spacing: -0.05em;
    transition: background-color 0.3s ease, transform 0.3s ease;

    &:hover,
    &:focus-visible {
        background-color: var(--at-theme-primary);
        color: var(--at-neutral-0);
    }

    &:hover .card-home-12-price__cta-icon svg,
    &:focus-visible .card-home-12-price__cta-icon svg {
        transform: translate(2px, -2px);
    }
}

.card-home-12-price__cta-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;

    svg {
        transition: transform 0.3s ease;
    }
}

/* ── Features list ──────────────────────────────── */
.card-home-12-price__features {
    list-style: none;
    margin: 0;
    padding: 24px 45px 32px;
    display: flex;
    flex-direction: column;
    row-gap: 20px;

    li {
        display: flex;
        align-items: center;
        column-gap: 12px;
    }
}

.card-home-12-price__feature-icon {
    flex-shrink: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 18px;
    height: 18px;
}

.card-home-12-price__feature-text {
    font-family: var(--at-ff-heading);
    font-weight: 500;
    font-size: 16px;
    line-height: 1.4;
    letter-spacing: -0.02em;
    color: var(--at-neutral-700);
}

/* ── Custom pricing CTA ─────────────────────────── */
.sec-5-home-12__custom {
    position: relative;
    display: flex;
    align-items: flex-start;
    column-gap: 10px;
    max-width: 483px;
    margin: 0 auto;
    padding-top: 8px;
}

.sec-5-home-12__custom-icon {
    flex-shrink: 0;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    margin-top: 4px;
}

.sec-5-home-12__custom-text {
    display: flex;
    flex-direction: column;
    row-gap: 17px;
}

.sec-5-home-12__custom-title {
    font-family: var(--at-ff-heading);
    font-weight: 600;
    font-size: 24px;
    line-height: 1.3;
    letter-spacing: -0.05em;
    color: var(--at-neutral-800);
}

.sec-5-home-12__custom-desc {
    font-family: var(--at-ff-heading);
    font-weight: 500;
    font-size: 20px;
    line-height: 1.35;
    letter-spacing: -0.02em;
    color: var(--at-neutral-700);
}

.sec-5-home-12__custom-link {
    color: var(--at-neutral-700);
    text-decoration: underline;
    text-underline-offset: 3px;
    transition: color 0.3s ease;

    &:hover,
    &:focus-visible {
        color: var(--at-theme-primary);
    }
}

/* ── Responsive ─────────────────────────────────── */
@media #{$xxl} {
    .sec-5-home-12 {
        padding-top: 100px;
        padding-bottom: 100px;
    }
}

@media #{$xl} {
    .sec-5-home-12 {
        padding-top: 90px;
        padding-bottom: 90px;
    }
    .sec-5-home-12__tables {
        gap: 20px;
    }
    .card-home-12-price__top {
        padding: 22px 24px 28px;
    }
    .card-home-12-price__features {
        padding: 22px 32px 28px;
    }
    .card-home-12-price__cta {
        padding: 14px 28px;
    }
}

@media #{$lg} {
    .sec-5-home-12 {
        padding-top: 80px;
        padding-bottom: 80px;
    }
    .sec-5-home-12__header {
        margin-bottom: 48px;
    }
    .sec-5-home-12__tables {
        gap: 18px;
        margin-bottom: 48px;
    }
    .card-home-12-price__top {
        padding: 20px 22px 26px;
    }
    .card-home-12-price__features {
        padding: 20px 26px 26px;
        row-gap: 16px;
    }
    .card-home-12-price__cta {
        padding: 14px 22px;
        font-size: 15px;
    }
    .card-home-12-price__amount {
        font-size: 42px;
        line-height: 46px;
    }
}

@media #{$md} {
    .sec-5-home-12 {
        padding-top: 64px;
        padding-bottom: 64px;
    }
    .sec-5-home-12__header {
        margin-bottom: 40px;
    }
    .sec-5-home-12__tables {
        grid-template-columns: 1fr;
        gap: 20px;
        max-width: 480px;
        margin-bottom: 40px;
    }
    .card-home-12-price__top {
        padding: 24px 28px 32px;
        min-height: auto;
    }
    .card-home-12-price__features {
        padding: 24px 32px 32px;
    }
    .sec-5-home-12__custom-title {
        font-size: 22px;
    }
    .sec-5-home-12__custom-desc {
        font-size: 18px;
    }
}

@media #{$sm} {
    .sec-5-home-12 {
        padding-top: 56px;
        padding-bottom: 56px;
    }
    .sec-5-home-12__header {
        margin-bottom: 32px;
        row-gap: 12px;
    }
    .sec-5-home-12__tables {
        grid-template-columns: 1fr;
        gap: 16px;
        margin-bottom: 32px;
    }
    .card-home-12-price__top {
        padding: 20px 22px 28px;
        min-height: auto;
    }
    .card-home-12-price__features {
        padding: 20px 26px 28px;
        row-gap: 14px;
    }
    .card-home-12-price__amount {
        font-size: 40px;
        line-height: 44px;
    }
    .sec-5-home-12__custom-title {
        font-size: 20px;
    }
    .sec-5-home-12__custom-desc {
        font-size: 16px;
    }
}

@media #{$xs} {
    .sec-5-home-12 {
        padding-top: 48px;
        padding-bottom: 48px;
    }
    .sec-5-home-12__header {
        margin-bottom: 28px;
    }
    .sec-5-home-12__tables {
        grid-template-columns: 1fr;
        gap: 14px;
        margin-bottom: 28px;
    }
    .card-home-12-price {
        border-radius: 14px;
    }
    .card-home-12-price__top {
        margin: 12px 12px 0;
        padding: 18px 18px 24px;
        border-radius: 12px;
    }
    .card-home-12-price__features {
        padding: 18px 20px 24px;
        row-gap: 12px;
    }
    .card-home-12-price__amount {
        font-size: 36px;
        line-height: 40px;
    }
    .card-home-12-price__cta {
        padding: 13px 20px;
        font-size: 14px;
    }
    .sec-5-home-12__dots {
        background-size: 64px 64px, 64px 64px;
        background-position: 0 0, 32px 32px;
    }
}
