@use '../../utils' as *;

/*----------------------------------------*/
/*  5.2 Postbox css
/*----------------------------------------*/

.postbox {
    &-item {
        &:not(:last-child) {
            border-bottom: 1px solid rgba(30, 30, 30, 0.08);
            padding-bottom: 50px;
            margin-bottom: 60px;
        }

        &:hover {
            & .postbox-thumb {
                & img {
                    transform: scale(1.1);
                }
            }
        }
    }

    &-thumb {
        border-radius: 42px;
        overflow: hidden;


        & img {
            border-radius: 42px;
            transition: all .8s ease;
        }
    }

    &-play-btn {
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);

        & a {
            height: 80px;
            width: 80px;
            display: inline-flex;
            align-items: center;
            justify-content: center;
            line-height: 77px;
            text-align: center;
            border-radius: 50%;
            background: rgba(255, 255, 255, 0.30);
            backdrop-filter: blur(5px);
            animation: animate-pulse 3s linear infinite;

            & svg {
                margin-left: 3px;
                display: inline-block;
            }
        }
    }
}

// Postbox scroll-zoom: ảnh full-width, mặt nạ hở 200x100px ở trung tâm, mở rộng dần khi scroll.
// Phần bị clip để lộ marquee text chạy ngang phía sau.
.postbox-scroll-zoom {
    .postbox-item-wrap {
        width: 100%;
        height: 200vh;
    }

    .postbox-item {
        display: flex;
        align-items: center;
        justify-content: center;
        width: 100%;
        height: 100vh;
    }

    .postbox-thumb {
        width: 100%;
        height: 100%;
        background-color: var(--at-neutral-50, #f5f5f5);
    }

    .postbox-scroll-zoom-img {
        width: 100%;
        height: 100%;
        object-fit: cover;
        clip-path: inset(calc(50% - 50px) calc(50% - 100px) calc(50% - 50px) calc(50% - 100px) round 4px);
        will-change: clip-path;
        position: relative;
        z-index: 2;
    }

    .postbox-scroll-zoom-play {
        z-index: 3;
    }

    .postbox-scroll-zoom-marquee {
        position: absolute;
        inset: 0;
        z-index: 1;
        display: flex;
        flex-direction: column;
        justify-content: space-around;
        align-items: stretch;
        padding: 4% 0;
        pointer-events: none;
        overflow: hidden;
        will-change: opacity;
    }

    .postbox-scroll-zoom-marquee-row {
        display: flex;
        width: 100%;
        overflow: hidden;
        white-space: nowrap;

        &.dir-left .postbox-scroll-zoom-marquee-track {
            animation: postbox-marquee-left 30s linear infinite;
        }

        &.dir-right .postbox-scroll-zoom-marquee-track {
            animation: postbox-marquee-right 35s linear infinite;
        }
    }

    .postbox-scroll-zoom-marquee-track {
        display: inline-flex;
        flex-shrink: 0;
        align-items: center;
        gap: 40px;
        font-family: inherit;
        font-weight: 600;
        font-size: clamp(48px, 8vw, 120px);
        line-height: 1;
        letter-spacing: -0.02em;
        text-transform: uppercase;
        color: var(--at-neutral-100, #dfdfdf);
        padding-right: 40px;

        & > span {
            display: inline-block;
            flex-shrink: 0;
        }
    }
}

@keyframes postbox-marquee-left {
    0% {
        transform: translateX(0);
    }
    100% {
        transform: translateX(-50%);
    }
}

@keyframes postbox-marquee-right {
    0% {
        transform: translateX(-50%);
    }
    100% {
        transform: translateX(0);
    }
}

@media (prefers-reduced-motion: reduce) {
    .postbox-scroll-zoom .postbox-scroll-zoom-marquee-row .postbox-scroll-zoom-marquee-track {
        animation: none;
    }
}