@use '../../utils' as *;

/*----------------------------------------*/
/*  sec-8-home-7 (Team — Dedicated Team + Staggered Portrait Grid)
/*----------------------------------------*/

.sec-8-home-7 {
    position: relative;
    padding: 120px 0;

    @media #{$xl,$lg,$md} {
        padding: 90px 0;
    }

    @media #{$sm,$xs} {
        padding: 60px 0;
    }

    // --- Left column (lead) ------------------------------------------------
    &__lead {
        padding-top: 60px;

        @media #{$xl} {
            padding-top: 40px;
        }

        @media #{$lg,$md,$sm,$xs} {
            padding-top: 0;
        }
    }

    &__eyebrow {
        color: var(--at-neutral-900, #1d1d1d);
        font-size: 16px;
        font-weight: 600;
        letter-spacing: -0.05em;

        svg {
            transition: transform .35s ease;
        }

        &:hover {
            color: var(--at-theme-primary);

            svg {
                transform: translate(2px, -2px);
            }
        }
    }

 // Huge display heading: spec is DM Sans Medium 124px / 124 line-height.
    &__heading {
        font-family: var(--at-heading-font);
        color: var(--at-neutral-900, #1d1d1d);
        font-size: clamp(3.5rem, 8.5vw, 7.75rem); // 56px → 124px
        font-weight: 500;
        line-height: 1;
        letter-spacing: -0.05em;

        // On desktop the phrase intentionally wraps to 2 lines ("Dedicated" /
        // "Team"). Cap width so the break happens naturally around 600px.
        max-width: 600px;

        @media #{$lg,$md,$sm,$xs} {
            max-width: 100%;
        }
    }

    &__desc {
        color: var(--at-neutral-900, #1d1d1d);
        font-size: 32px;
        font-weight: 400;
        line-height: 1.25;
        letter-spacing: -0.05em;
        max-width: 605px;

        @media #{$xl} {
            font-size: 26px;
        }

        @media #{$lg,$md} {
            font-size: 22px;
        }

        @media #{$sm,$xs} {
            font-size: 18px;
            max-width: 100%;
        }
    }

    // --- CTA: "Join our Team" pill + separate arrow pill ------------------
    &__cta-btn {
        display: inline-flex;
        align-items: center;
        height: 50px;
        padding: 0 27px;
        border-radius: 50px;
        background: var(--at-neutral-900, #1d1d1d);
        color: var(--at-neutral-0, #fefefe);
        font-family: var(--at-heading-font);
        font-size: 16px;
        font-weight: 600;
        letter-spacing: -0.05em;
        text-decoration: none;
        transition: background .35s ease, color .35s ease, transform .35s ease;

        &:hover {
            background: var(--at-theme-primary);
            color: var(--at-common-white);
            transform: translateX(2px);
        }
    }

    &__cta-arrow {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 50px;
        height: 50px;
        border-radius: 50%;
        background: var(--at-neutral-900, #1d1d1d);
        color: var(--at-neutral-0, #fefefe);
        transition: background .35s ease, transform .35s ease;

        svg {
            width: 20px;
            height: 20px;
            display: block;
            transition: transform .35s ease;
        }

        &:hover {
            background: var(--at-theme-primary);
            transform: rotate(-15deg);

            svg {
                transform: scale(1.1);
            }
        }
    }

    // --- Right column: staggered 2-col grid --------------------------------
    &__grid {
        display: grid;
        grid-template-columns: repeat(2, 1fr);
        gap: 30px;
        align-items: start;

        @media #{$md} {
            gap: 24px;
        }

        @media #{$sm,$xs} {
            grid-template-columns: 1fr;
            gap: 24px;
        }
    }

    &__col {
        display: flex;
        flex-direction: column;
        gap: 40px;

        @media #{$md} {
            gap: 24px;
        }

        @media #{$sm,$xs} {
            gap: 24px;
        }

 // Right column offsets down
        // (col 1 top = 140, col 2 top = 242).
        &--offset {
            @media (min-width: 992px) {
                margin-top: 100px;
            }
        }
    }

    // --- Card --------------------------------------------------------------
    &__card {
        position: relative;
        display: block;
        width: 100%;
        aspect-ratio: 407 / 549;
        border-radius: 16px;
        overflow: hidden;
        background: var(--at-neutral-100, #dfdfdf);
        text-decoration: none;
        isolation: isolate;

        &:hover {
            .sec-8-home-7__photo img {
                transform: scale(1.05);
            }

            .sec-8-home-7__badge {
                transform: translate(2px, -2px);
            }
        }
    }

    &__photo {
        position: absolute;
        inset: 0;
        overflow: hidden;

        img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            object-position: center top;
            transition: transform .7s ease;
        }
    }

 // Gradient fade + subtle backdrop blur
    // [2.985px] bg-gradient rgba(26,26,26,0) → #1a1a1a" overlay.
    &__info {
        position: absolute;
        left: 0;
        right: 0;
        bottom: 0;
        padding: 38px 40px 40px;
        height: 38%;
        color: var(--at-common-white, #fefefe);
        background: linear-gradient(
            to bottom,
            rgba(26, 26, 26, 0) 0%,
            rgba(26, 26, 26, 0.55) 45%,
            rgba(26, 26, 26, 1) 100%
        );
        backdrop-filter: blur(3px);
        -webkit-backdrop-filter: blur(3px);
        mask-image: linear-gradient(to bottom, transparent 0%, #000 35%);
        -webkit-mask-image: linear-gradient(to bottom, transparent 0%, #000 35%);
        display: flex;
        flex-direction: column;
        justify-content: flex-end;
        gap: 12px;
        pointer-events: none;

        @media #{$md,$sm,$xs} {
            padding: 28px 30px 30px;
        }
    }

    &__name {
        font-family: var(--at-heading-font);
        font-size: 32px;
        font-weight: 600;
        line-height: 1.15;
        letter-spacing: -0.05em;
        color: #fefefe;

        @media #{$xl,$lg} {
            font-size: 28px;
        }

        @media #{$md,$sm,$xs} {
            font-size: 26px;
        }
    }

    &__role {
        font-family: var(--at-heading-font);
        font-size: 18px;
        font-weight: 500;
        line-height: 1.3;
        letter-spacing: -0.02em;
        opacity: 0.8;
        color: #fefefe;
    }

    // --- Arrow badge (top-right of every card) ----------------------------
    &__badge {
        position: absolute;
        top: 20px;
        right: 20px;
        width: 40px;
        height: 40px;
        border-radius: 50%;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        background: var(--at-neutral-0, #fefefe);
        color: var(--at-neutral-900, #1d1d1d);
        transition: transform .35s ease, background .35s ease, color .35s ease;
        z-index: 2;

        svg {
            width: 15px;
            height: 14px;
            display: block;
        }

        &--dark {
            background: var(--at-neutral-900, #1d1d1d);
            color: var(--at-neutral-0, #fefefe);
        }
    }
}
